function lesson(title,objective,theory,example,practice,question,options,correct,source,duration){
 var hash=2166136261;for(var i=0;i<title.length;i++){hash^=title.charCodeAt(i);hash=Math.imul(hash,16777619);}var id='lesson-'+(hash>>>0).toString(36),kind=source===refs.js?'javascript':source===refs.py?'python':'english';
 var taskInstructions=kind==='javascript'?['Открой редактор кода и создай отдельный файл lesson.js.','Реализуй задание из блока ниже; не копируй готовое решение.','Запусти файл в подходящей среде (Node.js или браузер) и проверь минимум три сценария: обычный, граничный и ошибочный.','Исправь ошибки и запиши, почему решение работает.']:kind==='python'?['Открой редактор и создай файл lesson.py.','Напиши решение по условию ниже; раздели логику на понятные функции.','Запусти python lesson.py и проверь обычный, граничный и ошибочный ввод.','Если уместно, добавь pytest-тесты; запиши ожидаемый и фактический результат.']:['Прочитай правило и выпиши 5 ключевых слов или конструкций.','Выполни письменное задание ниже, используя собственные примеры, а не копируя образец.','Прочитай результат вслух; проверь грамматику, смысл и естественность формулировок.','Исправь ошибки и сохрани финальный текст или запись ответа.'];
 var deliverable=kind==='javascript'?'Файл lesson.js, рабочий результат запуска и три проверенных сценария.':kind==='python'?'Файл lesson.py, результат запуска и тесты/проверки трёх сценариев.':'Собственный письменный ответ и устная практика по теме урока.';
 var acceptanceCriteria=kind==='javascript'?'Код запускается без ошибок; результат соответствует условию; обычный, граничный и ошибочный случаи проверены.':kind==='python'?'Скрипт запускается; входные данные обработаны явно; проверки подтверждают ожидаемый результат.':'Задание выполнено полностью; собственные примеры корректны; смысл понятен при чтении вслух.';
 return {id:id,title:title,objective:objective,theory:theory+'\n\nРазбор примера: '+example,practice:practice,taskInstructions:taskInstructions,deliverable:deliverable,acceptanceCriteria:acceptanceCriteria,metric:'Выполни задание самостоятельно, сохрани указанный результат, проверь его по критериям и объясни ключевое решение без подсказки.',checkQuestion:question,quiz:{question:question,options:options,correctIndex:correct,answerExplanation:'Верный ответ: '+options[correct]+'. Он соответствует учебной цели: '+objective},duration:duration||15,steps:['Изучи цель и объяснение.','Разбери пример и предскажи результат до запуска.','Выполни задание и сохрани результат.','Проверь результат по критериям и ответь на вопрос без подсказки.'],sources:[source],commonMistakes:['Механически копировать пример без понимания причин.','Проверять только успешный сценарий и игнорировать граничные случаи.','Считать прочтение урока подтверждением освоения.']};
}
function module(id,title,lessons){return {id:id,emoji:'📘',title:title,lessons:lessons};}
var jsLessons=[
lesson('Среда JavaScript и модель выполнения','Понять роль движка, среды выполнения и спецификации языка.','ECMAScript задаёт семантику языка; движок исполняет код, а среда предоставляет host API. В браузере это DOM, fetch и события; в Node.js — файловая система, процессы и сетевые API. Глобальные объекты и доступные API зависят от среды. Не путай синтаксис языка с возможностями платформы.','Один и тот же чистый JS-модуль может работать в браузере и Node.js, но обращение к document доступно только в браузере.','Создай модуль без DOM-зависимостей, затем отдельно подключи его к браузерному адаптеру. Зафиксируй, какие API относятся к языку, а какие — к host environment.','Что определяет ECMAScript?',['Семантику и синтаксис языка','Все браузерные API','Только интерфейс Node.js'],0,refs.js),
lesson('Переменные, области видимости и TDZ','Безошибочно выбирать const, let и понимать область видимости.','const запрещает переназначение binding, но не делает вложенный объект неизменяемым. let допускает переназначение. Оба имеют блочную область видимости и temporal dead zone до объявления. var имеет функциональную область видимости и историческое hoisting-поведение; в современном коде его обычно избегают.','Внутри блока let x создаёт отдельный binding; чтение x до объявления в том же блоке приводит к ReferenceError.','Напиши три коротких примера: блочная область, TDZ и изменение свойства const-объекта. Для каждого предскажи результат до запуска.','Что именно гарантирует const?',['Глубокую неизменяемость объекта','Запрет переназначения binding','Функциональную область видимости'],1,refs.js),
lesson('Примитивы, ссылки и сравнение','Различать примитивные значения и ссылочные объекты.','Примитивы передаются как значения; объекты сравниваются по идентичности ссылки. Два объекта с одинаковыми полями не равны по ===, если это разные экземпляры. Для структурного сравнения нужна явная стратегия, учитывающая вложенность, типы, циклы и специальные значения.','({a:1} === {a:1}) даёт false, потому что литералы создают два объекта.','Реализуй функцию shallowEqual для объектов без вложенных структур. Опиши её ограничения и напиши тесты на null, массивы и разные ссылки.','Почему два одинаковых объектных литерала не равны через ===?',['Потому что объекты сравниваются по идентичности','Потому что === сравнивает только строки','Потому что свойства автоматически сортируются'],0,refs.js),
lesson('Функции, замыкания и чистые вычисления','Использовать функции как значения и понимать лексическое окружение.','Функция захватывает переменные из лексического окружения создания — это замыкание. Замыкание хранит доступ к binding, а не снимок значения. Чистая функция возвращает результат только из аргументов и не создаёт наблюдаемых побочных эффектов; это упрощает тестирование и композицию.','makeCounter создаёт локальный count и возвращает функцию, которая продолжает иметь доступ к этому binding после завершения makeCounter.','Создай фабрику независимых счётчиков, затем покрой тестами независимость экземпляров и последовательность значений.','Что сохраняет замыкание?',['Ссылку на лексическое окружение','Только исходный текст функции','Глобальный объект браузера'],0,refs.js),
lesson('Асинхронность: Promise и обработка ошибок','Строить предсказуемые асинхронные цепочки.','Promise представляет будущее завершение операции: fulfilled или rejected. then возвращает новый Promise; ошибка распространяется по цепочке до ближайшего обработчика catch. async-функция всегда возвращает Promise. await приостанавливает выполнение текущей async-функции, но не блокирует поток целиком.','try { const data = await load(); } catch (error) { report(error); } отделяет успешный путь от обработки отказа.','Реализуй функцию загрузки с timeout, отменой через AbortController и нормализацией ошибок. Проверь timeout, HTTP-ошибку и успешный ответ.','Что возвращает async-функция?',['Всегда Promise','Всегда обычный объект','Только undefined'],0,refs.js),
lesson('Модули, контракты и тестируемость','Проектировать небольшие модули с явными контрактами.','ES modules используют import/export и имеют собственную область модуля. Хороший модуль скрывает детали реализации, экспортирует минимальный API и не выполняет тяжёлые побочные эффекты при импорте. Контракт описывает входы, выходы, ошибки и инварианты.','Функция parseConfig может возвращать валидированную структуру или бросать типизированную ошибку; вызывающий код не должен угадывать состояние.','Раздели парсер конфигурации и IO-адаптер. Добавь unit-тесты валидных данных, отсутствующих полей, неверных типов и неожиданных значений.','Какой принцип повышает изолированную тестируемость модуля?',['Минимальный API и явные зависимости','Глобальные переменные для всех данных','Скрытая запись в localStorage при импорте'],0,refs.js)
];
var pyLessons=[
lesson('Интерпретатор, скрипт и виртуальное окружение','Настроить воспроизводимую среду Python-проекта.','Версия интерпретатора влияет на доступный синтаксис и стандартную библиотеку. Виртуальное окружение изолирует зависимости проекта от системного Python. Фиксация зависимостей и версии runtime уменьшает различия между разработкой и CI.','python -m venv .venv создаёт окружение; зависимости устанавливаются выбранным интерпретатором через python -m pip.','Создай проект с .venv, requirements.txt и README с командами установки, запуска и тестирования. Проверь чистую установку в новом окружении.','Для чего нужен venv?',['Изолировать зависимости проекта','Ускорять любой Python-код автоматически','Компилировать Python в машинный код'],0,refs.py),
lesson('Объекты, имена и изменяемость','Понимать связывание имён с объектами и мутабельность.','В Python имя связывается с объектом; присваивание не копирует объект автоматически. Списки и словари изменяемы, строки и кортежи — нет. Изменяемые значения по умолчанию в функциях опасны: объект создаётся один раз при определении функции и разделяется вызовами.','def add(x, items=[]): создаёт общий список для последующих вызовов; безопаснее использовать None и создавать новый список внутри.','Напиши тест, который выявляет общий mutable default, затем исправь функцию и проверь независимость вызовов.','Почему list в аргументе по умолчанию может быть ошибкой?',['Он создаётся один раз и переиспользуется','Python запрещает изменять списки','Аргументы по умолчанию копируются при каждом вызове'],0,refs.py),
lesson('Функции, аргументы и контракты типов','Проектировать функции с предсказуемыми интерфейсами.','Позиционные и именованные аргументы улучшают читаемость; *args собирает дополнительные позиционные аргументы, **kwargs — именованные. Type hints документируют ожидаемые типы и помогают статическим анализаторам, но сами по себе не обеспечивают runtime-валидацию. Функция должна иметь понятный контракт ошибок и побочных эффектов.','def total(prices: list[float]) -> float описывает ожидаемый интерфейс, но входные данные всё равно требуют проверки, если границы доверия это предполагают.','Реализуй calculate_total с типами, проверкой отрицательных цен и тестами на пустой список, корректные значения и неверный ввод.','Что дают type hints без дополнительного валидатора?',['Документируют контракт и помогают статическому анализу','Автоматически проверяют каждый аргумент во время выполнения','Гарантируют отсутствие логических ошибок'],0,refs.py),
lesson('Исключения и управление ресурсами','Обрабатывать ошибки по типам и безопасно освобождать ресурсы.','Перехватывай конкретные ожидаемые исключения; широкий except Exception допустим на границе приложения для логирования и контролируемого завершения, но не для сокрытия дефектов. Контекстный менеджер with гарантирует корректное освобождение ресурса при нормальном выходе и исключении.','with open(path, encoding="utf-8") as f: автоматически закрывает файл даже при исключении внутри блока.','Напиши чтение JSON-файла: отдельно обработай FileNotFoundError, JSONDecodeError и ошибки доступа. Не превращай повреждённый файл в пустой конфиг молча.','Какова ключевая гарантия with для поддерживаемого контекстного менеджера?',['Вызов механизма завершения ресурса при выходе из блока','Автоматическое исправление содержимого файла','Подавление всех исключений'],0,refs.py),
lesson('Итераторы, генераторы и память','Выбирать ленивую обработку для больших потоков данных.','Итератор реализует протокол __iter__/__next__; генераторная функция с yield создаёт итератор и выдаёт значения по запросу. Ленивость уменьшает пиковое потребление памяти, но не делает вычисление бесплатным: важны стоимость каждого шага, повторный проход и обработка ошибок.','Чтение большого файла построчно позволяет обрабатывать запись за записью вместо загрузки всего файла в память.','Создай генератор фильтрации событий из файла и сравни пиковую память с вариантом, который читает весь файл целиком.','Какое свойство характерно для генератора?',['Значения вычисляются по мере итерации','Он всегда хранит весь результат в списке','Его можно повторно обходить без ограничений'],0,refs.py),
lesson('Пакеты, тесты и архитектурные границы','Строить Python-проект, который удобно сопровождать.','Разделяй доменную логику, адаптеры IO и интерфейс. Тестируй поведение через публичные контракты, изолируй сеть и файловую систему через внедрение зависимостей. pytest parametrization помогает проверять множество случаев одним тестом; фикстуры управляют тестовым окружением.','Сервис расчёта заказа принимает репозиторий как зависимость и не открывает базу данных напрямую внутри доменной функции.','Собери пакет с src layout, pytest, линтером и CI. Добавь unit-тесты, интеграционный тест репозитория и негативные сценарии.','Что обеспечивает внедрение зависимости?',['Позволяет подменять внешние детали и тестировать логику изолированно','Убирает необходимость проверять ошибки','Гарантирует линейную производительность'],0,refs.py)
];
var englishLessons=[
lesson('A1 · Представление себя и базовый порядок слов','Строить короткие утвердительные предложения о себе.','Базовая английская модель — Subject + Verb + Complement. В настоящем времени глагол to be согласуется с подлежащим: I am, you/we/they are, he/she/it is. В английском обычно нельзя опускать подлежащее так, как это возможно в русском.','I am a student. She is from Spain. They are ready. Вопрос с be образуется перестановкой: Are you ready?','Запиши 8 фраз о себе: имя, место, учёба, интересы и ежедневные действия. Преврати две фразы в вопросы и две — в отрицания.','Выбери правильное предложение.',['She are a student.','She is a student.','She am a student.'],1,refs.en),
lesson('A2 · Прошлые события и связный рассказ','Описывать завершённые события и последовательность действий.','Past Simple используется для завершённых действий в прошлом. Правильные глаголы обычно получают -ed; неправильные имеют отдельную форму. В вопросах и отрицаниях используется did, после которого основной глагол возвращается к базовой форме. Связность улучшают first, then, after that, finally.','Yesterday I visited my friend. Then we went to the library. Did you call him? I did not call him.','Напиши рассказ на 100–120 слов о прошедшем дне, используя минимум 5 глаголов Past Simple и 4 маркера последовательности.','Как правильно задать вопрос о завершённом действии?',['Did you went there?','Did you go there?','Do you went there?'],1,refs.en),
lesson('B1 · Аргументация и сложные предложения','Обосновывать мнение и связывать тезис с причиной и примером.','На B1 важно не только выражать мнение, но и разворачивать его: claim → reason → example → qualification. Союзы because, although, while, therefore и however задают логические отношения. Следи за тем, чтобы however не подменял причинную связь, а although не дублировался с but в одной конструкции.','Although the tool is expensive, it saves time because it automates repetitive checks.','Напиши 180–220 слов о выборе учебного инструмента. Дай тезис, две причины, пример, ограничение и вывод.','Какую функцию обычно выполняет although?',['Вводит уступку или контраст','Обозначает точное время','Вводит прямую речь'],0,refs.en),
lesson('B2 · Нюанс, регистр и точность формулировки','Адаптировать лексику и тон к аудитории и цели.','B2 предполагает гибкое использование регистра: нейтральный, формальный, профессиональный и разговорный. Модальные глаголы и hedging выражают степень уверенности: may, might, is likely to, appears to. Категоричные утверждения требуют более сильных оснований, чем осторожные выводы.','The results suggest a possible improvement звучит осторожнее и точнее, чем The results prove that it works, если данные ограничены.','Перепиши один текст в трёх регистрах: сообщение коллеге, формальный запрос и краткое устное объяснение. Сохрани смысл и измени тон.','Какой вариант выражает осторожный вывод?',['This proves the method always works.','The findings may indicate an improvement.','There is no possible alternative.'],1,refs.en),
lesson('C1 · Синтез источников и академическая позиция','Собирать аргумент из нескольких источников без искажения их выводов.','На C1 нужно различать позицию автора, данные, метод и ограничения. Синтез объединяет источники по общим темам и расхождениям, а не пересказывает каждый по очереди. Используй attribution verbs (argues, reports, observes), квалификаторы и явные ссылки. Не усиливай корреляцию до причинности и не приписывай источнику вывод, которого он не делал.','One study reports a short-term association, whereas the longitudinal analysis finds no robust effect after adjustment.','Сравни два открытых англоязычных источника по одной теме. Напиши 250 слов: общий вывод, расхождения, качество доказательств и собственная позиция.','Что является корректным синтезом?',['Последовательный пересказ каждого текста без сопоставления','Сопоставление выводов, методов и ограничений источников','Выбор только источника, подтверждающего мнение'],1,refs.en),
lesson('C2 · Риторическая точность и стилистический контроль','Создавать сложные тексты с точным смыслом, регистром и риторической структурой.','C2 — не набор редких слов, а почти полный контроль над оттенками смысла, идиоматичностью, жанром и риторикой. Точность требует выбора слов по коллокациям, управления информационной структурой, уместной компрессии и осознанного варьирования синтаксиса. Сложность не должна снижать ясность.','В экспертном докладе можно вынести оговорку в subordinate clause, но ключевое ограничение должно оставаться однозначным для читателя.','Подготовь 500-словный аналитический текст и 3-минутную устную версию для другой аудитории. Проведи редактуру на точность, коллокации, логическую связность и стилистическую уместность.','Что лучше всего характеризует уровень C2?',['Использование максимально редких слов в каждом предложении','Гибкий контроль сложного языка, смысла и регистра','Безошибочное знание только грамматических правил'],1,refs.en)
];

/* Reviewed expansion batch 2: distinct applied skills, not target-count placeholders. */
jsLessons.push(
lesson('Строгие сравнения и числовые граничные случаи','Избегать ошибок равенства, NaN и неявного приведения типов.','Операторы === и !== исключают большинство сюрпризов неявного преобразования, но NaN не равен даже самому себе. Для проверки NaN используй Number.isNaN; глобальный isNaN сначала приводит аргумент к числу. Перед сравнением чисел определяй допустимую точность и диапазон, особенно для вычислений с плавающей точкой.','0.1 + 0.2 !== 0.3; проверка с epsilon сравнивает Math.abs(a-b) с выбранным допуском, который должен соответствовать масштабу задачи.','Реализуй функцию nearlyEqual(a,b,epsilon), определи поведение для NaN и Infinity и добавь тесты на ноль, отрицательные числа, большие значения и некорректный epsilon.','Как корректно проверить, что x — NaN?',['x === NaN','Number.isNaN(x)','Boolean(x)'],1,refs.js,20),
lesson('Обработка ошибок как часть API-контракта','Создавать ошибки, которые помогают вызывающему коду восстановиться.','Исключение должно описывать отказ, а не маскировать его. Создавай собственные классы ошибок для устойчиво различимых категорий, сохраняй cause при оборачивании и не включай секреты или персональные данные в сообщения. На границе приложения преобразуй внутренние ошибки в безопасный формат ответа; не возвращай stack клиенту.','throw new ValidationError("Invalid email", { cause: error }) сохраняет первопричину, если класс ошибки поддерживает стандартные параметры Error.','Спроектируй API валидации с ValidationError и DependencyError. Проверь instanceof, cause, сериализацию безопасного ответа и отсутствие токенов в логах.','Зачем сохранять cause при оборачивании ошибки?',['Чтобы не терять первопричину сбоя','Чтобы автоматически повторить запрос','Чтобы скрыть все ошибки от тестов'],0,refs.js,25),
lesson('Event loop: очереди задач и микрозадач','Предсказывать порядок выполнения синхронного кода, Promise и таймеров.','Сначала выполняется текущий синхронный стек. После его опустошения среда обрабатывает очередь микрозадач, включая реакции Promise; затем выполняются задачи очереди событий, например callback таймера. Точные детали host scheduling зависят от среды, поэтому не используй таймеры как механизм точной синхронизации.','console.log("A"); setTimeout(()=>console.log("B")); Promise.resolve().then(()=>console.log("C")); console.log("D") выводит A, D, C, B в обычной браузерной модели.','Напиши пять фрагментов с Promise.then, queueMicrotask и setTimeout. До запуска зафиксируй ожидаемый порядок и объясни его; отдельно сравни браузер и Node.js документацию.','Что обычно выполнится раньше после завершения текущего стека: Promise.then или setTimeout(..., 0)?',['Promise.then как микрозадача','Таймер как задача','Порядок всегда случайный'],0,refs.js,25)
);
pyLessons.push(
lesson('Области видимости и LEGB','Предсказывать, какое имя будет найдено и где допустимо присваивание.','Python разрешает имена по правилу LEGB: Local, Enclosing, Global, Builtins. Присваивание внутри функции обычно создаёт локальное имя; global и nonlocal явно меняют это поведение. Избегай скрытой мутации глобального состояния: передавай зависимости параметрами и возвращай результат.','Вложенная функция может читать переменную внешней функции; для переназначения этой переменной требуется nonlocal.','Создай вложенную функцию-счётчик с nonlocal, затем перепиши её как объект с явным состоянием. Сравни тестируемость и побочные эффекты.','Что означает E в LEGB?',['Enclosing scope','External package','Execution thread'],0,refs.py,20),
lesson('Декораторы и сохранение метаданных','Применять декораторы без потери исходной сигнатуры и документации.','Декоратор — вызываемый объект, который принимает функцию и возвращает замену или обёртку. functools.wraps переносит основные метаданные исходной функции и устанавливает __wrapped__. Параметризованный декоратор добавляет внешний уровень фабрики. Декоратор не должен незаметно менять контракт исключений или тип результата.','@wraps(func) над wrapper позволяет инструментам introspection видеть имя и docstring исходной функции.','Напиши декоратор измерения времени с functools.wraps. Проверь имя, docstring, возвращаемое значение, исключения и поведение функции с keyword-only аргументами.','Для чего нужен functools.wraps?',['Сохранять метаданные обёрнутой функции','Автоматически кешировать каждый вызов','Делать функцию асинхронной'],0,refs.py,25),
lesson('Конкурентность: потоки, процессы и asyncio','Выбирать модель выполнения по характеру нагрузки и ограничениям runtime.','Потоки удобны для перекрытия IO ожидания; процессы позволяют использовать несколько ядер для CPU-bound задач с ценой сериализации и IPC. asyncio эффективно обслуживает множество кооперативных IO-задач, но блокирующий вызов внутри event loop задерживает остальные корутины. Измеряй реальную нагрузку и учитывай ограничения GIL конкретной версии и реализации Python.','При скачивании множества URL asyncio может быть уместен; при тяжёлых вычислениях изображения чаще подходят процессы или нативные библиотеки.','Сравни три реализации одной задачи: IO-bound загрузка и CPU-bound вычисление. Замерь время, память, ошибки отмены и влияние блокирующей операции.','Что обычно подходит для большого числа неблокирующих IO-задач?',['asyncio','Один процесс на каждую строку кода','Синхронный busy-wait'],0,refs.py,30)
);
englishLessons.push(
lesson('A1 · Вопросы с do и короткие ответы','Задавать простые вопросы о привычках и отвечать кратко.','Для Present Simple с обычными глаголами используем do/does: Do you work? Does she study? После does основной глагол остаётся в базовой форме. Короткие ответы повторяют вспомогательный глагол: Yes, I do. No, she doesn’t. С глаголом be do/does не используется.','Does he play tennis? — Yes, he does. Are you tired? — No, I’m not.','Составь 6 вопросов о распорядке дня и дай короткие ответы. Затем исправь ошибки в трёх предложениях с does.','Как правильно спросить «Она работает здесь?»',['Does she work here?','Does she works here?','Do she work here?'],0,refs.en,15),
lesson('A1 · Лексика повседневных действий и частотность','Описывать распорядок с наречиями частотности.','Наречия always, usually, often, sometimes и never обычно стоят перед смысловым глаголом, но после be: I usually walk; She is often busy. Их значение приблизительно задаёт частоту, а не точный процент. Для ясности добавляй временные выражения: every day, twice a week.','I usually study in the evening. He is never late for class.','Опиши неделю в 8–10 предложениях, используя пять наречий частотности и три выражения времени. Проверь позицию наречия.','Где обычно стоит usually перед обычным глаголом?',['Перед смысловым глаголом','Всегда в конце предложения','Перед подлежащим'],0,refs.en,15),
lesson('A2 · Countable и uncountable nouns','Выбирать корректные квантификаторы для исчисляемых и неисчисляемых существительных.','Исчисляемые существительные имеют формы единственного и множественного числа: a book, books. Неисчисляемые обычно не употребляются с a/an и не получают обычное множественное число: information, advice, water. Используй many/few для исчисляемых и much/little для неисчисляемых; some/any применяются шире.','How many books? How much information? A piece of advice — единица для неисчисляемого advice.','Отредактируй список покупок и рабочее письмо: исправь ошибки с advice, information, furniture, apples и rice.','Как правильно сказать?',['many information','much information','an information'],1,refs.en,18),
lesson('A2 · Просьбы, предложения и вежливые формулы','Формулировать уместные просьбы и предложения в бытовых ситуациях.','Can you…? — прямой нейтральный запрос; Could you…? звучит вежливее. Would you mind + -ing — более мягкая формула, после mind используется герундий. Для предложения подойдут Would you like…? и Shall we…? Выбор зависит от отношений и ситуации.','Could you send me the address, please? Would you mind waiting a moment?','Составь диалог: попроси помощь, предложи альтернативу и вежливо откажись. Используй три разные конструкции.','Какая форма грамматически верна?',['Would you mind to wait?','Would you mind waiting?','Would you mind wait?'],1,refs.en,18),
lesson('B1 · Present Perfect и временная перспектива','Различать опыт, результат и завершённое время в прошлом.','Present Perfect связывает прошлое с настоящим: жизненный опыт, недавний результат или состояние, продолжающееся до сих пор. Past Simple задаёт завершённое время в прошлом. Не употребляй Present Perfect с конкретным завершённым маркером вроде yesterday или in 2020.','I have visited Rome (опыт). I visited Rome in 2022 (конкретный завершённый период).','Напиши 10 пар предложений, противопоставляя опыт и конкретное прошлое время. Объясни выбор времён.','Какой вариант естественен с yesterday?',['I have seen him yesterday.','I saw him yesterday.','I have saw him yesterday.'],1,refs.en,20),
lesson('B1 · Условные предложения первого и второго типа','Обсуждать реальные будущие последствия и гипотетические ситуации.','First conditional описывает возможное условие: if + Present Simple, will + base verb. Second conditional описывает маловероятную или воображаемую ситуацию: if + Past Simple, would + base verb. В придаточном if обычно не ставится will для обычного условия.','If it rains, we will stay home. If I had more time, I would learn another language.','Напиши 4 реальных плана и 4 гипотетические ситуации. Для каждого объясни, насколько условие реально.','Какой вариант соответствует first conditional?',['If I will see him, I tell him.','If I see him, I will tell him.','If I saw him, I will tell him.'],1,refs.en,20),
lesson('B2 · Пассивный залог и фокус информации','Использовать passive voice, когда важнее действие или результат, чем исполнитель.','Passive строится как be + past participle; время выражается формой be. Пассив уместен в отчётах, процессах и описании результатов, но чрезмерное использование скрывает ответственность. Agent with by добавляй, когда исполнитель важен.','The report was approved yesterday. The data are being reviewed by the audit team.','Перепиши 8 предложений active/passive и объясни, как меняется фокус и ясность ответственности.','Как строится базовый passive?',['be + past participle','have + infinitive','do + gerund'],0,refs.en,20),
lesson('B2 · Collocations и естественная сочетаемость','Повышать естественность речи через устойчивые словосочетания.','Грамматически возможные слова не всегда образуют естественное сочетание. Английский часто использует make a decision, take responsibility, conduct research, highly likely. Учить лексику полезно блоками и в контексте, отмечая регистр и типичные дополнения.','We conducted research и made a decision — устойчивые сочетания, которые звучат естественнее буквального перевода.','Собери 15 collocations из открытого словаря, составь контекстные предложения и проверь сочетаемость по корпусу или авторитетному словарю.','Какое сочетание обычно естественно?',['do a decision','make a decision','create a decision'],1,refs.en,20),
lesson('C1 · Инверсия для акцента и формального регистра','Распознавать и уместно использовать инверсию после ограничительных наречий.','После начальных выражений Never, Rarely, Seldom, Not only и Only then в формальном стиле часто используется инверсия вспомогательного глагола и подлежащего. Это средство акцента, а не обязательное украшение каждого предложения.','Rarely have we seen such consistent results. Only after the review did the team approve the release.','Перепиши 6 нейтральных предложений с инверсией, затем объясни, почему в каждом случае выбран такой акцент.','Какой вариант корректен?',['Rarely we have seen this.','Rarely have we seen this.','Rarely did we saw this.'],1,refs.en,25),
lesson('C1 · Дискурсивные маркеры и логика аргумента','Связывать абзацы, показывая уступку, следствие и уточнение.','Discourse markers задают отношения между частями аргумента: nevertheless — уступка, consequently — следствие, conversely — противопоставление, specifically — уточнение. Маркер должен соответствовать логике, иначе текст кажется связным лишь поверхностно.','The sample was small; nevertheless, the pattern warrants further investigation.','Отредактируй аналитический текст, заменив повторяющиеся however/therefore на точные маркеры. Для каждого перехода подпиши логическое отношение.','Какое слово вводит следствие?',['Consequently','Nevertheless','Conversely'],0,refs.en,25),
lesson('C2 · Идиоматичность без перегруженности','Редактировать сложный текст ради естественности, ясности и точного регистра.','На C2 идиоматичность означает не обилие идиом, а естественный выбор коллокаций, фразовых глаголов, синтаксиса и информационного акцента. Сложная конструкция оправдана только если точнее передаёт смысл. Избегай кальки с родного языка и чрезмерно книжных формул в нейтральном жанре.','The proposal gained traction звучит естественно в деловом контексте; буквальная конструкция received a big popularity — нет.','Отредактируй 300-словный текст носительски-ориентированным способом: отметь кальки, коллокации, регистр и места, где простая формулировка лучше сложной.','Что является признаком идиоматичности?',['Максимальная длина предложений','Естественные сочетания и уместный регистр','Использование редких слов независимо от контекста'],1,refs.en,30)
);


/* Curated content batch 3 — additional distinct learning outcomes. */
jsLessons.push(
lesson('Прототипная цепочка и классы','Объяснять делегирование свойств и выбирать композицию вместо наследования там, где она проще.','Каждый обычный объект связан с прототипом. При чтении свойства движок ищет его сначала у объекта, затем по цепочке прототипов до null. class предоставляет синтаксис для конструктора и методов прототипа, но не отменяет прототипную модель. Наследование задаёт отношение «является», композиция собирает поведение из независимых частей.','Object.create(proto) создаёт объект с заданным прототипом; Object.hasOwn проверяет собственное свойство без обхода цепочки.','Создай базовый объект с методом, два объекта-наследника и альтернативную реализацию через композицию. Сравни расширяемость и тестируемость.','Где обычно размещаются методы экземпляра, объявленные в class?',['В прототипе класса','В JSON-конфигурации','В глобальном объекте'],0,refs.js,25),
lesson('Итераторы, iterable и генераторы','Создавать ленивые последовательности и понимать протокол итерации.','Iterable предоставляет Symbol.iterator, который возвращает iterator с методом next. Генераторная функция function* при вызове возвращает итератор; yield выдаёт значение и приостанавливает выполнение. Ленивость позволяет обрабатывать большие последовательности без хранения всего результата в памяти.','function* range(n) { for (let i=0;i<n;i++) yield i; } вычисляет следующее значение по запросу.','Реализуй генератор пакетной обработки записей. Проверь пустую последовательность, ранний break и корректное освобождение ресурсов в finally.','Какое ключевое слово выдаёт значение из генератора?',['yield','await','return*'],0,refs.js,25),
lesson('DOM: делегирование событий и безопасность','Обрабатывать динамические элементы без множества обработчиков.','Событие обычно всплывает от целевого элемента к предкам. Делегирование устанавливает один обработчик на стабильном контейнере и определяет источник через event.target или closest. Для пользовательского текста используй textContent, а не вставку HTML. Проверяй границу контейнера, чтобы вложенные элементы не активировали чужие действия.','container.addEventListener("click", e => { const button=e.target.closest("[data-action]"); if (!button || !container.contains(button)) return; ... });','Сделай список с динамически добавляемыми кнопками. Реализуй делегирование, клавиатурную доступность и тест на клик по вложенной иконке.','Какое преимущество даёт делегирование событий?',['Обработка динамических потомков одним обработчиком','Автоматическая защита от XSS во всех случаях','Отмена всплытия всех событий браузера'],0,refs.js,25),
lesson('Хранилища браузера и миграция схемы','Безопасно хранить небольшие пользовательские настройки с версионированием.','localStorage синхронен и хранит строки; JSON.parse может завершиться ошибкой, а доступ к storage может быть запрещён политикой браузера. Хранилище не является базой данных с транзакциями и не подходит для секретов. Версионируй схему, валидируй данные и делай миграции идемпотентными.','Запись {version:2,settings:{...}} позволяет выбрать миграцию v1→v2; при ошибке парсинга приложение должно иметь безопасный fallback, не уничтожая исходную запись без необходимости.','Реализуй загрузку настроек с версиями 1 и 2, миграцию, валидацию и тесты на повреждённый JSON и недоступный storage.','Почему нельзя считать localStorage доверенной базой?',['Данные могут быть изменены или повреждены, а API синхронен','Он всегда шифрует значения автоматически','Он гарантирует транзакции между вкладками'],0,refs.js,30),
lesson('Производительность: профилирование до оптимизации','Находить реальную причину замедления по измерениям.','Оптимизация начинается с воспроизводимого сценария и профиля, а не с догадок. Разделяй CPU, сеть, layout, память и время ожидания. Сравнивай медиану и распределение нескольких запусков, фиксируй устройство и объём данных. Избегай микрооптимизаций, которые усложняют код без измеримого выигрыша.','Performance API позволяет измерить участок через performance.mark и performance.measure; DevTools помогает найти long tasks и лишние перерисовки.','Выбери медленный экран, собери baseline, найди три крупнейших затратных участка, измени один фактор и повтори замер. Запиши эффект и погрешность.','Что должно предшествовать оптимизации?',['Профилирование воспроизводимого сценария','Переписывание всего кода на более короткий синтаксис','Добавление кеша без измерений'],0,refs.js,25),
lesson('Безопасность JavaScript: XSS и границы доверия','Не допускать превращения пользовательских данных в исполняемую разметку.','XSS возникает, когда недоверенные данные попадают в опасный контекст как HTML, атрибут, URL или JavaScript. Предпочитай textContent и безопасные DOM API; при необходимости HTML-рендеринга используй проверенный sanitizer и контекстное кодирование. CSP — дополнительный слой, а не замена безопасной обработки данных.','element.textContent = userInput отображает текст; element.innerHTML = userInput интерпретирует его как разметку и может создать XSS.','Проведи threat model мини-приложения: найди все источники пользовательских данных и места вставки в DOM. Исправь опасные sinks и добавь регрессионные payload-тесты.','Как безопасно вывести произвольный пользовательский текст?',['Через textContent','Через innerHTML без очистки','Через eval'],0,refs.js,30)
);
pyLessons.push(
lesson('Исключения и управление ресурсами','Гарантировать закрытие файлов и соединений даже при ошибке.','try/except обрабатывает ожидаемые исключения; else выполняется при отсутствии ошибки; finally подходит для гарантированной очистки. Контекстный менеджер with вызывает протокол входа и выхода, позволяя освобождать ресурс при любом исходе. Не перехватывай Exception без конкретной стратегии восстановления.','with open(path, encoding="utf-8") as file: гарантирует закрытие файла после выхода из блока.','Реализуй чтение файла с понятной обработкой FileNotFoundError и UnicodeDecodeError. Добавь тесты, подтверждающие закрытие ресурса при исключении.','Какой механизм предпочтителен для файлов?',['with и контекстный менеджер','Глобальная переменная с дескриптором','Оставить файл открытым до завершения процесса'],0,refs.py,20),
lesson('Итераторы и генераторы Python','Обрабатывать большие данные лениво и ограничивать потребление памяти.','Итератор реализует __iter__ и __next__; генераторная функция с yield автоматически создаёт итератор. Генераторы вычисляют элементы по требованию и могут быть одноразовыми. Для повторного прохода нужно создать новый генератор или сохранить данные в подходящем хранилище.','(line.strip() for line in file) создаёт ленивую последовательность строк без списка всех строк в памяти.','Напиши генератор чтения CSV-подобного файла построчно, фильтрацию и агрегирование. Сравни пиковую память со списочным вариантом.','Что вернёт вызов функции с yield?',['Объект-генератор','Список всех значений','Всегда coroutine'],0,refs.py,25),
lesson('Модули, пакеты и границы ответственности','Разделять доменную логику, адаптеры и инфраструктуру.','Модуль — файл с пространством имён; пакет объединяет модули. Импорт выполняет код верхнего уровня, поэтому побочные эффекты при импорте усложняют тестирование. Циклические импорты обычно указывают на неудачные границы ответственности. Держи доменную логику независимой от файловой системы и сети.','Функция расчёта комиссии принимает значения и возвращает результат; отдельный адаптер читает конфигурацию и вызывает функцию.','Разложи небольшой CLI-проект на domain, services и adapters. Убедись, что unit-тесты домена работают без сети и файлов.','Что обычно является признаком плохой границы модуля?',['Импорт запускает сетевой запрос и меняет состояние','Модуль экспортирует небольшой API','Зависимости передаются явно'],0,refs.py,25),
lesson('Тестирование pytest: фикстуры и параметризация','Строить компактные тесты с изолированным состоянием.','Фикстуры создают и освобождают общие ресурсы с заданным scope. Параметризация прогоняет один контракт на множестве входов. Тест должен проверять наблюдаемое поведение, а не внутреннюю реализацию. Для внешних систем используй контрактные тесты и контролируемые тестовые среды, не подменяя реальные интеграционные проверки фиктивными результатами.','@pytest.mark.parametrize("value,expected", [...]) позволяет проверить границы одного правила несколькими примерами.','Покрой функцию нормализации 12 случаями, добавь fixture для временной директории и тест ошибки чтения. Раздели unit и integration тесты.','Для чего нужна параметризация pytest?',['Проверить один контракт на наборе входов','Автоматически скрыть все падения тестов','Запустить тесты только один раз'],0,refs.py,25),
lesson('Типизация Python: Protocol и generics','Описывать структурные интерфейсы и переиспользуемые типобезопасные функции.','Protocol задаёт структурный контракт: объект подходит, если имеет требуемые методы и атрибуты, даже без явного наследования. TypeVar и Generic сохраняют отношения типов между входом и выходом. Статическая типизация помогает находить ошибки до запуска, но не заменяет проверку недоверенных данных на границах приложения.','def first[T](items: Sequence[T]) -> T использует параметр типа; точный синтаксис зависит от поддерживаемой версии Python.','Определи Protocol для репозитория пользователей и generic-функцию выбора первого элемента. Проверь совместимость через выбранный статический анализатор.','Что описывает Protocol?',['Структурный интерфейс объекта','Обязательный базовый класс для всех реализаций','Механизм сериализации JSON'],0,refs.py,30),
lesson('Профилирование и оптимизация Python','Измерять CPU и память и выбирать подходящий алгоритм.','Сначала измерь тип нагрузки. cProfile показывает распределение времени по вызовам; timeit полезен для небольших повторяемых операций; tracemalloc помогает исследовать выделения памяти. Часто улучшение алгоритмической сложности важнее замены синтаксиса. Измеряй на репрезентативных данных и проверяй корректность после оптимизации.','Замена вложенного поиска O(n²) на множество для проверки принадлежности часто даёт больший выигрыш, чем микрооптимизация цикла.','Профилируй обработку набора из 10k и 100k записей. Найди узкое место, предложи изменение сложности и сравни время и память.','Какой инструмент помогает найти горячие функции CPU?',['cProfile','json.dumps','venv'],0,refs.py,25)
);
englishLessons.push(
lesson('A1 · Артикли a, an и the','Выбирать базовые артикли в описании предметов и знакомых объектов.','A/an вводит один исчисляемый предмет, который упоминается впервые или не является конкретным для собеседника. An выбирается по начальному звуку, а не букве. The указывает на объект, который собеседникам уже известен или однозначно определяется контекстом. Во множественном числе и с неисчисляемыми существительными общий смысл часто выражается без артикля.','I saw a dog. The dog was friendly. She is an engineer.','Опиши комнату в 8 предложениях: впервые введи пять предметов с a/an, затем повторно упомяни их с the.','Какой вариант правильный?',['an university','a university','the university при любом первом упоминании'],1,refs.en,15),
lesson('A1 · There is и there are','Сообщать о наличии предметов в единственном и множественном числе.','There is используется с единственным числом и неисчисляемыми существительными; there are — с множественным. Вопрос строится перестановкой be: Is there…? Are there…? Отрицание: There isn’t / There aren’t. Для описания комнаты добавляй предлоги места.','There is a desk near the window. There are two chairs next to it.','Опиши свою комнату или воображаемую квартиру в 10 предложениях и составь четыре вопроса о расположении предметов.','Как правильно?',['There are a lamp.','There is a lamp.','There is two lamps.'],1,refs.en,15),
lesson('A2 · Сравнительная и превосходная степени','Сравнивать людей, предметы и варианты с корректными формами прилагательных.','Короткие прилагательные часто образуют comparative через -er и superlative через -est; длинные — через more и most. Есть неправильные формы good–better–best и bad–worse–worst. Than вводит объект сравнения; the обычно сопровождает превосходную степень перед существительным.','This route is shorter than the other one. It is the most convenient option.','Сравни три телефона по пяти критериям, используй минимум четыре сравнительные и три превосходные формы.','Какова сравнительная степень good?',['gooder','better','more good'],1,refs.en,18),
lesson('A2 · Предлоги времени и места','Использовать in, on и at в типичных временных и пространственных контекстах.','Для времени at обычно указывает точку (at 7), on — день или дату (on Monday), in — месяц, год или часть дня (in June, in 2026, in the morning). Для места at обозначает точку/место деятельности, in — внутри пространства, on — на поверхности. Устойчивые сочетания нужно учить в контексте.','We meet at 6 on Friday in the library. The keys are on the table.','Составь расписание недели и описание квартиры, включив 12 предложений с in/on/at. Отметь исключения и устойчивые выражения.','Как правильно сказать «в понедельник»?',['in Monday','on Monday','at Monday'],1,refs.en,18),
lesson('B1 · Reported speech и согласование времён','Передавать чужие слова, сохраняя смысл и временные ориентиры.','При вводном глаголе в прошедшем времени часто происходит backshift: present становится past, will — would, can — could. Но с актуальными фактами и если временная перспектива не изменилась, сдвиг не всегда обязателен. Местоимения и указатели времени/места меняются по контексту.','“I am busy,” she said → She said that she was busy.','Преобразуй 10 прямых реплик в косвенную речь. Для трёх случаев объясни, почему backshift необязателен или неуместен.','Как обычно меняется will в reported speech после said?',['would','did','has'],0,refs.en,20),
lesson('B1 · Relative clauses: defining и non-defining','Уточнять существительные придаточными определительными предложениями.','Defining relative clause необходима для идентификации предмета и обычно не отделяется запятыми. Non-defining добавляет дополнительную информацию и выделяется запятыми; в ней нельзя использовать that. Who относится к людям, which — к предметам и животным, whose обозначает принадлежность; where — место.','The engineer who fixed the server is here. My laptop, which I bought last year, is still reliable.','Соедини 12 пар предложений через relative clauses. Отметь, где информация определяющая, а где дополнительная.','Какое слово обычно нельзя использовать в non-defining clause?',['which','who','that'],2,refs.en,20),
lesson('B2 · Модальные глаголы дедукции','Выражать степень уверенности о настоящем и прошлом.','Must может выражать сильный вывод, might/may/could — возможность, can’t — сильную уверенность в невозможности. Для прошлого используются modal + have + past participle: must have forgotten, might have left, can’t have known. Это оценка доказательств, а не абсолютное доказательство.','The lights are off; they might have gone home. He can’t have finished already — the task started five minutes ago.','Напиши 8 выводов по описанным уликам: четыре о настоящем и четыре о прошлом. Укажи степень уверенности и альтернативное объяснение.','Как выразить сильный вывод о прошлом?',['must have + past participle','must to have + infinitive','must had + past participle'],0,refs.en,22),
lesson('B2 · Условные конструкции смешанного типа','Связывать прошлое условие с настоящим результатом и наоборот.','Mixed conditionals соединяют разные временные планы. If + Past Perfect может описывать нереализованное прошлое условие с результатом сейчас: If I had studied medicine, I would be a doctor now. If + Past Simple может описывать текущее состояние, повлиявшее на прошлый результат. Выбирай форму по смыслу, а не по механическому шаблону.','If she had accepted the offer, she would be living abroad now.','Напиши шесть mixed conditionals: три о прошлом влиянии на настоящее и три о текущем состоянии, повлиявшем на прошлое.','Какое предложение описывает прошлое условие и результат сейчас?',['If I had trained, I would be fitter now.','If I train, I would be fitter yesterday.','If I would train, I had been fitter now.'],0,refs.en,22),
lesson('C1 · Номинализация и плотность академического текста','Управлять плотностью информации без потери ясности и ответственности.','Номинализация превращает процесс или качество в существительное: the team implemented → the implementation. Она помогает связывать идеи и создавать компактный академический регистр, но чрезмерная номинализация скрывает действующее лицо и утяжеляет текст. Выбирай активный глагол, когда важны действие и ответственность.','The committee rejected the proposal яснее, чем The rejection of the proposal was undertaken by the committee.','Отредактируй 250 слов: сократи перегруженные номинализации, сохрани нужные тематические связи и явно обозначь ответственных участников.','Когда активная глагольная конструкция предпочтительнее?',['Когда важно ясно назвать действующее лицо и действие','Всегда, без исключений','Только в художественной прозе'],0,refs.en,25),
lesson('C1 · Прагматика: смягчение несогласия','Выражать несогласие профессионально, не размывая содержательную позицию.','Прагматическая уместность зависит от статуса, контекста и цели разговора. Формулы I see your point, however…; I would question whether…; The evidence seems to suggest… смягчают тон, но не должны скрывать вывод. Уточняй критерий разногласия: данные, метод, интерпретация или приоритет.','I agree with the objective; my concern is whether the proposed metric captures it accurately.','Подготовь три версии несогласия: коллеге, руководителю и публичному экспертному обсуждению. В каждой обозначь общий пункт и точное расхождение.','Что делает профессиональное несогласие конструктивным?',['Точное указание предмета разногласия и оснований','Личная оценка собеседника','Отказ объяснять позицию'],0,refs.en,25),
lesson('C2 · Ирония, импликатура и контекст','Распознавать подразумеваемый смысл, который не выражен буквально.','Импликатура возникает, когда слушатель выводит дополнительный смысл из контекста и принципов общения. Ирония может означать противоположное буквальному высказыванию, но зависит от общего знания, интонации и ситуации. Не трактуй косвенный смысл как гарантированный: проверяй альтернативные интерпретации и культурные различия.','“That was a brilliant idea” после очевидной неудачи может быть иронией, но без контекста фраза неоднозначна.','Разбери шесть коротких диалогов: отдели буквальное значение, возможную импликатуру, контекстные подсказки и альтернативное прочтение.','Что необходимо для надёжной интерпретации иронии?',['Контекст и общие знания участников','Только словарное значение слов','Обязательное наличие редкой лексики'],0,refs.en,25),
lesson('C2 · Перевод смысловых оттенков и register shift','Сохранять прагматический эффект при переносе текста между жанрами и аудиториями.','Перевод и переформулирование требуют сохранять не только денотативный смысл, но и степень категоричности, дистанцию, эмоциональную окраску и жанровую функцию. Register shift меняет форму под аудиторию, но не должен незаметно менять доказательную силу утверждения. Проверяй коллокации и культурно обусловленные коннотации.','The proposal is untenable в экспертном заключении может стать We do not think the proposal can work в устном объяснении без изменения сути оценки.','Адаптируй один аналитический абзац для научной статьи, деловой записки и устного брифинга. Отметь сохранённые тезисы и изменённые прагматические средства.','Что должно оставаться неизменным при корректном register shift?',['Смысл и доказательная сила ключевого утверждения','Длина каждого предложения','Все исходные идиомы дословно'],0,refs.en,30)
);


/* Curated content batch 4 — applied engineering and CEFR progression. */
jsLessons.push(
lesson('TypeScript interoperability and runtime validation','Разделять статическую проверку типов и проверку внешних данных во время выполнения.','TypeScript удаляет типовую информацию при компиляции и не проверяет JSON, полученный из сети. Любые внешние данные следует считать unknown, проверять структуру валидатором или собственными type guards и только затем использовать как доменные типы. Типы описывают контракт разработчикам, runtime-проверки защищают границы системы.','const raw: unknown = await response.json(); после проверки isUser(raw) значение можно безопасно использовать как User.','Спроектируй функцию parseApiUser для недоверенного JSON. Проверь отсутствующие поля, неверные типы, дополнительные свойства и некорректные значения.','Гарантирует ли интерфейс TypeScript корректность JSON во время выполнения?',['Нет, нужна runtime-валидация','Да, интерфейсы автоматически проверяют сеть','Да, если включён strict mode'],0,refs.js,25),
lesson('Сетевые запросы: HTTP-контракты и повторные попытки','Обрабатывать HTTP-статусы, таймауты и повторы без усиления нагрузки.','fetch отклоняет Promise при сетевых ошибках, но не при HTTP 4xx/5xx — нужно проверять response.ok. Повторять безопасно только операции, для которых повтор не создаёт дублирующий эффект; учитывай идемпотентность, Retry-After, экспоненциальную задержку с jitter и общий deadline.','Для GET можно повторить временный 503 с ограниченным backoff; POST платежа нельзя слепо повторять без idempotency key.','Реализуй HTTP-клиент с таймаутом, отменой, ограниченным retry для 429/503 и тестами на идемпотентность.','Почему нельзя безусловно повторять любой POST?',['Повтор может создать дублирующее действие','POST никогда не поддерживает JSON','fetch автоматически запрещает повтор'],0,refs.js,30),
lesson('Конкурентные задачи: Promise.all и ограничение параллелизма','Управлять конкурентностью и частичными отказами набора задач.','Promise.all отклоняется при первом rejection, но не отменяет остальные операции автоматически. Promise.allSettled собирает все результаты. Неограниченный запуск тысяч запросов может исчерпать лимиты сети и памяти; применяй очередь с ограничением concurrency и отмену через AbortSignal.','Пул из четырёх работников обрабатывает очередь, сохраняя ограничение одновременно активных запросов.','Напиши ограниченный пул задач, который сохраняет порядок результатов, поддерживает отмену и корректно обрабатывает частичные ошибки.','Какой метод возвращает итог каждого Promise независимо от успеха?',['Promise.allSettled','Promise.race','Promise.resolve'],0,refs.js,30),
lesson('Наблюдаемость frontend: ошибки и производительность','Добавлять измеримые сигналы без утечки персональных данных.','Наблюдаемость объединяет логи, метрики и трассировки. Frontend должен фиксировать тип ошибки, версию приложения, маршрут и технический контекст, но не токены, пароли и лишние персональные данные. Метрики производительности связывай с пользовательским сценарием; sampling и лимиты защищают бюджет и приватность.','Отправляй error category и release id, а идентификатор пользователя заменяй безопасным псевдонимом только при наличии основания и политики хранения.','Определи схему событий для загрузки экрана и сетевой ошибки. Добавь redaction секретов, sampling и тесты на отсутствие чувствительных полей.','Какие данные нельзя отправлять в telemetry без необходимости?',['Токены и пароли','Версию релиза','Код категории ошибки'],0,refs.js,25),
lesson('Релизная стратегия и обратимая поставка','Выпускать изменения с контролируемым риском и планом отката.','Безопасный релиз включает автоматические проверки, небольшую область изменений, feature flags при необходимости, мониторинг ключевых метрик и проверенный rollback. Миграции данных должны учитывать совместимость старой и новой версии приложения. «Деплой завершён» не означает, что пользовательский сценарий проверен.','Expand-and-contract migration сначала добавляет совместимое поле, затем переводит чтение/запись и лишь позже удаляет старое.','Составь release checklist для изменения схемы локального хранилища и UI. Опиши canary, критерии остановки и rollback без потери данных.','Что является обязательным элементом риск-контролируемого релиза?',['Проверенный план отката','Удаление старой схемы до миграции','Отключение мониторинга после деплоя'],0,refs.js,25)
);
pyLessons.push(
lesson('Датаклассы и модели доменных данных','Описывать неизменяемые и валидируемые структуры предметной области.','dataclasses генерируют методы вроде __init__ и __repr__ на основе полей. frozen=True запрещает обычное переназначение полей, но не делает вложенные изменяемые объекты глубоко неизменяемыми. Не путай удобную структуру данных с полноценной runtime-валидацией внешнего ввода.','@dataclass(frozen=True) class Money: amount: Decimal; currency: str задаёт компактную модель, но инварианты валюты и суммы нужно проверить отдельно.','Сделай доменные модели Money и UserSettings. Добавь инварианты, тесты на некорректные значения и объясни, почему Decimal лучше float для денежных расчётов.','Что означает frozen=True?',['Запрет обычного переназначения полей экземпляра','Глубокая неизменяемость всех вложенных объектов','Автоматическая проверка внешнего JSON'],0,refs.py,25),
lesson('Дескрипторы и свойства','Контролировать доступ к атрибутам через property и протокол дескрипторов.','property позволяет валидировать или вычислять значение при чтении и записи, сохраняя синтаксис атрибута. Дескрипторы реализуют __get__, __set__ или __delete__ и позволяют переиспользовать поведение между классами. Не прячь тяжёлый IO или неожиданную мутацию за обычным чтением свойства.','@property def full_name(self) вычисляет значение из first_name и last_name без отдельного хранимого поля.','Реализуй property для нормализации email и дескриптор PositiveNumber. Проверь чтение, запись, удаление и ошибки.','Какой метод дескриптора вызывается при присваивании атрибуту?',['__set__','__iter__','__call__'],0,refs.py,25),
lesson('Контекстные менеджеры собственного типа','Создавать безопасные области управления ресурсами.','Контекстный менеджер реализует __enter__ и __exit__; альтернативно применяется contextlib.contextmanager. __exit__ получает информацию об исключении и может подавить его, вернув True — делать это следует только осознанно. Контекст должен гарантировать освобождение ресурса и не скрывать сбой.','@contextmanager может открыть транзакцию, yield управление вызывающему коду и выполнить commit либо rollback в зависимости от исхода.','Реализуй контекстный менеджер временной настройки окружения, который восстанавливает исходное значение даже при исключении. Добавь тесты вложенности и отказа.','Когда вызывается __exit__?',['При выходе из блока with, в том числе при исключении','Только если блок завершился успешно','При импорте модуля'],0,refs.py,25),
lesson('Асинхронные генераторы и потоковая обработка','Обрабатывать асинхронные источники без накопления всех элементов.','Асинхронный генератор использует async def и yield; потребление выполняется через async for. Это удобно для сетевых потоков и постраничной загрузки. Backpressure и отмена должны быть частью контракта: производитель не должен бесконечно накапливать данные, если потребитель медленнее.','async for item in stream_pages(client) обрабатывает элементы по мере поступления.','Создай async generator для постраничного API, добавь ограничение скорости, отмену и тест на раннее прекращение чтения.','Как потребляется асинхронный генератор?',['Через async for','Только через list()','Через обычный for во всех случаях'],0,refs.py,30),
lesson('Архитектура сервисов и dependency injection','Изолировать бизнес-логику от транспорта, БД и внешних API.','Dependency injection передаёт сервису нужные интерфейсы вместо создания инфраструктуры внутри бизнес-метода. Это упрощает тестирование и замену реализации. Порты и адаптеры помогают держать доменную модель независимой от HTTP-фреймворка и конкретной базы. Абстракция оправдана, когда отражает реальную границу изменения.','OrderService(repo, payment_gateway) принимает интерфейсы репозитория и платёжного шлюза, а не импортирует глобальные клиенты.','Спроектируй сервис регистрации заказа с портами репозитория и платежей. Напиши unit-тесты бизнес-правил и интеграционный тест реального адаптера в отдельной среде.','Какое преимущество даёт dependency injection?',['Явные зависимости и изоляция бизнес-логики','Автоматическое ускорение каждого запроса','Отказ от необходимости интеграционных тестов'],0,refs.py,30)
);
englishLessons.push(
lesson('A1 · Past Simple глагола be','Говорить о состоянии и местоположении в прошлом.','Was используется с I/he/she/it, were — с you/we/they. Отрицание: was not/wasn’t и were not/weren’t. Вопрос строится перестановкой: Was she…? Were they…? Для обычных глаголов Past Simple используется другая модель с did.','I was at home yesterday. They weren’t at school. Were you tired?','Напиши 8 предложений о вчерашнем дне: утверждения, отрицания и вопросы с was/were.','Как правильно спросить «Они были дома?»',['Was they at home?','Were they at home?','Did they were at home?'],1,refs.en,15),
lesson('A1 · Притяжательные формы и местоимения','Различать my/mine, your/yours и притяжательное окончание ’s.','Притяжательные определители (my, your, his, her, its, our, their) стоят перед существительным. Притяжательные местоимения (mine, yours, hers) заменяют сочетание с существительным. ’s часто показывает принадлежность человеку: Anna’s bag. Не путай its и it’s (it is/it has).','This is my phone. This phone is mine. It’s Anna’s phone.','Опиши принадлежность десяти предметов в классе, используй обе формы и три конструкции с ’s.','Как правильно сказать «Эта книга моя»?',['This book is my.','This book is mine.','This is mine book.'],1,refs.en,15),
lesson('A2 · Future plans: going to и Present Continuous','Различать намерения, прогнозы по признакам и договорённости.','Be going to часто выражает намерение или прогноз на основании видимых признаков. Present Continuous описывает согласованную договорённость с конкретной организацией. Will часто используется для спонтанного решения, обещания или прогноза-мнения. Контекст важнее механического правила.','I’m meeting Sam at six (договорённость). Look at those clouds; it’s going to rain (признаки).','Опиши планы на выходные: три договорённости, три намерения и два прогноза по видимым признакам.','Какой вариант лучше описывает уже согласованную встречу?',['I am meeting Alex at six.','I meet Alex maybe someday.','I will meeting Alex at six.'],0,refs.en,18),
lesson('A2 · Наречия образа действия','Описывать, как выполняется действие, с помощью adverbs of manner.','Многие наречия образуются добавлением -ly: careful–carefully, slow–slowly. Но есть исключения: good–well, fast–fast. Наречие обычно уточняет глагол, тогда как прилагательное описывает существительное или состояние после linking verb.','She speaks clearly. The explanation is clear. He drives well.','Опиши выполнение пяти действий, используя наречия. Исправь предложения, где прилагательное ошибочно использовано вместо наречия.','Как правильно?',['She sings beautiful.','She sings beautifully.','She beautifully is sings.'],1,refs.en,18),
lesson('B1 · Gerund и infinitive после глаголов','Выбирать форму -ing или to-infinitive в зависимости от управляющего глагола и смысла.','Некоторые глаголы обычно требуют gerund (enjoy doing), другие — infinitive (decide to do). У некоторых меняется смысл: stop doing — прекратить действие; stop to do — остановиться, чтобы выполнить другое действие. Учить нужно конструкцию целиком, включая объект и предлог.','I remember locking the door (помню факт) vs I remembered to lock the door (не забыл выполнить действие).','Составь 12 пар предложений с remember, stop, try, regret и предложи контекст, который объясняет выбор формы.','Что обычно означает stop smoking?',['Прекратить курить','Остановиться, чтобы покурить','Начать курить'],0,refs.en,20),
lesson('B1 · Phrasal verbs и отделяемые частицы','Понимать значение фразовых глаголов и порядок местоимений.','Фразовый глагол объединяет глагол с частицей или предлогом. У отделяемых конструкций объект-существительное может стоять до или после частицы, но местоимение обычно ставится между глаголом и частицей: turn it off. Значение часто идиоматично и зависит от контекста.','Please turn off the light / Please turn the light off / Please turn it off.','Подготовь карточки для 12 phrasal verbs из одной темы (работа или учёба), добавь контекстные примеры и тест на порядок слов.','Как правильно с местоимением?',['Turn off it.','Turn it off.','Turn it of.'],1,refs.en,20),
lesson('B2 · Cleft sentences для фокуса','Выделять важную часть сообщения через it-cleft и wh-cleft.','Cleft sentence перераспределяет информационный фокус. It was the timing that caused the delay выделяет причину; What we need is a reliable baseline выносит ключевой элемент в конец. Такая конструкция полезна для контраста, но частое использование делает текст тяжёлым.','It was the missing test data that delayed the release.','Перепиши восемь нейтральных предложений в cleft constructions и объясни, какую часть информации ты выделил.','Какой вариант является it-cleft?',['It was the data that changed the result.','The data changed result it.','What was the data changed.'],0,refs.en,22),
lesson('B2 · Ellipsis и substitution','Избегать ненужного повтора, сохраняя однозначность высказывания.','Ellipsis опускает восстанавливаемый из контекста материал; substitution заменяет его словами one, do, so, neither и другими. Эти средства делают речь естественнее, но чрезмерное опущение может вызвать двусмысленность. В формальном тексте проверяй, можно ли однозначно восстановить пропущенную часть.','I thought the first proposal would work, but it didn’t. Here one заменяет существительное, а do — действие в соответствующем контексте.','Отредактируй диалог на 200 слов: убери избыточные повторы через ellipsis и substitution, затем проверь ясность без исходного текста.','Что обычно заменяет one в конструкции the red one?',['Исчисляемое существительное в единственном числе','Любой глагол','Целое предложение без контекста'],0,refs.en,22),
lesson('C1 · Hedging и калибровка уверенности','Соотносить категоричность научного вывода с силой доказательств.','Hedging выражает ограничения знания: appears to, may, tends to, is consistent with. Слишком сильные формулы (proves, always, inevitably) требуют чрезвычайно сильных оснований. Недостаточная определённость тоже вредна: если результат устойчив, не следует искусственно ослаблять его. Калибруй язык по дизайну исследования и неопределённости.','The results are consistent with an association точнее, чем X causes Y, если исследование наблюдательное.','Перепиши 10 выводов с разной силой данных: описательное наблюдение, корреляция, эксперимент и мета-анализ. Обоснуй каждый модальный выбор.','Какой вывод осторожнее и точнее для наблюдательной корреляции?',['X proves Y causes Z.','The findings are consistent with an association.','X always determines Y.'],1,refs.en,25),
lesson('C1 · Cohesion: reference, substitution и lexical chains','Создавать связность между предложениями без повторения одних и тех же слов.','Cohesion обеспечивается грамматическими ссылками (this, these, such), заменой, опущением и лексическими цепочками синонимов/гиперонимов. Неоднозначное this без ясного antecedent затрудняет чтение. Повтор ключевого термина иногда лучше, чем искусственная вариативность синонимов.','This approach reduces latency. Such a reduction matters most under peak load — ссылка должна однозначно указывать на предыдущую идею.','Отредактируй пять абзацев: устрани неоднозначные this/it/they, выстрой лексические цепочки и сохрани точные термины там, где синонимы меняют смысл.','Что делает ссылку this корректной?',['Ясный antecedent в контексте','Максимально дальнее положение от исходной идеи','Замена любого существительного'],0,refs.en,25),
lesson('C2 · Синтаксическая компрессия и читаемость','Сжимать сложную аргументацию без потери логических отношений.','Синтаксическая компрессия объединяет взаимосвязанные идеи через subordinate clauses, participial phrases и номинальные группы. Но длинная цепочка вложенных конструкций увеличивает когнитивную нагрузку. Сохраняй главную мысль в главной части предложения и раскрывай ограничения там, где они помогают интерпретации.','Although the sample was limited, the pattern, replicated in a second cohort, warrants cautious follow-up лучше структурировать так, чтобы ограничение не терялось в середине.','Сократи 350-словный отчёт до 220 слов, сохрани тезис, ограничения, причинные оговорки и логические связи. Проведи обратную проверку смысла.','Какой критерий важнее при синтаксической компрессии?',['Сохранение логики и читаемости','Максимальная длина одного предложения','Удаление всех оговорок'],0,refs.en,30),
lesson('C2 · Межкультурная прагматика и вежливость','Адаптировать прямоту и речевые акты к межкультурному контексту.','Степень прямоты просьб, отказов и критики зависит от отношений, институциональных норм и культурного контекста. Нельзя сводить культуры к жёстким стереотипам: внутри любой группы есть вариативность. Выбирай формулировки по ситуации, проверяй реакцию собеседника и при необходимости уточняй намерение.','Could we revisit the deadline? может быть мягче прямого We must change the deadline, но выбор зависит от полномочий и срочности.','Подготовь варианты просьбы, отказа и обратной связи для трёх рабочих контекстов. Объясни, какие сигналы статуса, срочности и близости влияют на формулировку.','Почему нельзя механически переносить норму вежливости между культурами?',['Контекст и нормы общения вариативны, возможны неверные обобщения','Потому что грамматика везде одинакова','Потому что вежливость не зависит от отношений'],0,refs.en,30)
);


/* Curated content batch 5 — senior engineering, systems design and advanced English. */
jsLessons.push(
lesson('Архитектура состояния frontend-приложения','Выбирать модель состояния по области владения, частоте изменений и требованиям согласованности.','Локальное состояние компонента не следует глобализировать без причины. Серверное состояние отличается кэшированием, актуальностью и синхронизацией; URL-состояние должно поддерживать навигацию и совместное использование. Разделяй источники истины, производные значения и временный UI state. Нормализация уменьшает дублирование сущностей, но требует дисциплины обновлений.','Фильтр списка может храниться в URL, открытое состояние модального окна — локально, а данные профиля — в серверном query cache.','Спроектируй state map для каталога: фильтры, пагинация, профиль, черновик формы и модалка. Для каждого поля укажи owner, persistence, invalidation и тесты гонок.','Что обычно подходит для фильтра, который должен сохраняться в ссылке?',['URL query parameters','Локальная переменная обработчика','Случайное поле DOM'],0,refs.js,30),
lesson('Web Workers и перенос вычислений','Убирать тяжёлые CPU-задачи из главного потока с учётом стоимости обмена сообщениями.','Web Worker выполняется в отдельном глобальном контексте и не имеет прямого доступа к DOM. Данные обычно копируются при postMessage; transferable объекты позволяют передать владение буфером. Worker полезен для тяжёлых вычислений, но маленькая задача может стать медленнее из-за сериализации и запуска.','worker.postMessage(buffer, [buffer]) передаёт ArrayBuffer без обычного копирования и делает исходный буфер недоступным в отправителе.','Вынеси сортировку большого набора в Worker. Измерь время основного потока, стоимость передачи данных и поведение при отмене/ошибке.','Может ли Web Worker напрямую изменять DOM документа?',['Нет, взаимодействует через сообщения','Да, если импортировать document','Да, но только синхронно'],0,refs.js,30),
lesson('Память JavaScript: утечки и жизненный цикл объектов','Находить удерживаемые ссылки и устранять утечки памяти.','Сборщик мусора освобождает объекты, недостижимые из корней. Утечки возникают, когда ненужные объекты остаются достижимыми: незакрытые listeners, таймеры, глобальные кэши, замыкания и detached DOM. WeakMap подходит для метаданных, не удерживающих ключи, но не является универсальной заменой управлению жизненным циклом.','При удалении компонента нужно снять обработчик или использовать AbortSignal в addEventListener, чтобы привязать listener к контролируемому жизненному циклу.','Создай экран с динамическими компонентами и повторными mount/unmount. Используй heap snapshots, найди retained objects и исправь утечку.','Что удерживает объект от сборки мусора?',['Достижимая ссылка от корня GC','Наличие комментария в коде','Имя переменной в исходнике после выхода из области'],0,refs.js,30),
lesson('Service Worker: жизненный цикл и стратегия кеширования','Проектировать обновления offline-first приложения без устаревших и частично установленных ресурсов.','Service Worker проходит install, waiting, activate и fetch. Установка должна атомарно проверять обязательные ресурсы; при ошибке не активировать неполный кеш. Cache-first подходит стабильным статическим ресурсам, network-first — навигации с fallback, stale-while-revalidate — данным, где допустима краткая устарелость. Очистка старых кешей должна быть ограничена собственным префиксом.','Новый worker может ждать закрытия старых вкладок; skipWaiting и clients.claim меняют момент переключения и требуют совместимости кода.','Смоделируй релиз с двумя версиями приложения. Проверь offline install, частичный отказ ресурса, обновление вкладки и откат на предыдущий стабильный cache.','Почему install должен завершаться ошибкой при недоступном обязательном ресурсе?',['Чтобы не активировать неполный offline cache','Чтобы браузер удалил все пользовательские данные','Чтобы сеть всегда была отключена'],0,refs.js,30),
lesson('Архитектурные ADR и технические компромиссы','Фиксировать причины технических решений и условия их пересмотра.','Architecture Decision Record описывает контекст, проблему, рассматриваемые варианты, решение, последствия и статус. ADR помогает будущей команде понять не только что выбрали, но и почему отвергли альтернативы. Хорошее решение явно называет компромиссы и сигналы, при которых его следует пересмотреть.','ADR может зафиксировать выбор IndexedDB вместо localStorage для больших структурированных офлайн-данных и критерии миграции при росте объёма.','Напиши ADR для выбора между localStorage, IndexedDB и серверной БД. Добавь требования, альтернативы, последствия, риски и measurable revisit triggers.','Что отличает полезный ADR от простого описания реализации?',['Контекст, альтернативы, причины и последствия решения','Только список изменённых файлов','Только субъективная оценка автора'],0,refs.js,25),
lesson('Staff-level техническое лидерство: RFC и межкомандные контракты','Согласовывать архитектурные изменения между командами через проверяемые контракты.','Staff Engineer работает с проблемами, пересекающими границы команды: согласует API, модели данных, миграции, SLO, владение и rollout. RFC должен описывать проблему и варианты до выбора решения, обозначать владельцев, открытые вопросы и критерии успеха. Консенсус не равен единогласию; важны прозрачные решения и ответственность.','RFC API v2 включает схему совместимости, срок deprecation, план dual-read, метрики ошибок и ответственных за каждый этап.','Подготовь RFC межкомандного изменения API: stakeholders, compatibility matrix, migration plan, SLO, risks, decision log и rollout gates.','Какой артефакт лучше всего фиксирует согласование межкомандного изменения до реализации?',['RFC с контрактами и критериями решения','Личное сообщение без контекста','Коммит без описания'],0,refs.js,35)
);
pyLessons.push(
lesson('GIL, free-threaded Python и границы переносимости','Учитывать модель потоков конкретной сборки Python, не полагаясь на упрощённые мифы о GIL.','В традиционных сборках CPython GIL ограничивает одновременное выполнение Python bytecode потоками в одном процессе, но детали зависят от версии и реализации. Появляются free-threaded сборки, где совместимость расширений и стоимость синхронизации требуют отдельной проверки. Потокобезопасность приложения нельзя выводить только из наличия или отсутствия GIL.','CPU-bound workload может масштабироваться процессами в обычной сборке; при free-threaded варианте нужно измерять конкуренцию, contention и совместимость зависимостей.','Сравни потоки и процессы на CPU-bound и IO-bound нагрузке. Зафиксируй версию/сборку Python, число ядер, throughput, latency и корректность при гонках.','Почему нельзя считать GIL универсальной гарантией потокобезопасности?',['Потому что операции и сторонние расширения имеют собственные условия синхронизации','Потому что GIL существует только в Windows','Потому что потоки не могут делить память'],0,refs.py,30),
lesson('Asyncio cancellation и structured concurrency','Строить иерархию асинхронных задач с предсказуемой отменой.','Отмена asyncio Task доставляется как CancelledError в точку приостановки. Корректный код выполняет cleanup в finally и обычно повторно поднимает отмену. TaskGroup в современных версиях Python структурирует жизненный цикл дочерних задач: выход из блока ждёт их завершения и отменяет соседние при ошибке. Не глотай отмену без чёткой причины.','async with asyncio.TaskGroup() as group: group.create_task(...) связывает задачи с областью ответственности родителя.','Реализуй агрегатор трёх источников через TaskGroup. Смоделируй ошибку одного источника, отмену пользователя и гарантированную очистку ресурсов.','Что обычно следует сделать после cleanup при получении CancelledError?',['Повторно поднять исключение отмены','Молча продолжить бесконечный цикл','Преобразовать его в успешный пустой результат всегда'],0,refs.py,30),
lesson('Транзакции, изоляция и конкурентные обновления','Предотвращать потерянные обновления и нарушения инвариантов при параллельной записи.','Транзакция объединяет операции в атомарную единицу. Уровни изоляции определяют видимость конкурентных изменений и возможные аномалии. Optimistic concurrency использует version/ETag и условную запись; pessimistic locking блокирует конфликтующий доступ. Повторы транзакций требуют идемпотентной бизнес-логики.','UPDATE accounts SET balance=... WHERE id=? AND version=? позволяет обнаружить конфликт по числу затронутых строк и повторить операцию после перечитывания.','Спроектируй перевод между счетами: инварианты, атомарность, конкурентные запросы, retry, idempotency key и тесты на lost update.','Что помогает обнаружить конкурентное изменение без блокировки строки заранее?',['Optimistic version check','Повторное чтение только в памяти','Увеличение таймаута клиента'],0,refs.py,35),
lesson('Очереди сообщений и гарантии доставки','Различать at-most-once, at-least-once и effectively-once обработку.','Очереди обычно обеспечивают определённую гарантию доставки, но повторная доставка возможна. At-least-once требует идемпотентного consumer; дедупликация и transactional outbox уменьшают рассогласование между записью в БД и публикацией события. Exactly-once в реальной распределённой системе обычно ограничено конкретной границей и не отменяет проектирование идемпотентности.','Outbox записывает бизнес-изменение и событие в одной транзакции; отдельный publisher доставляет событие с повтором.','Смоделируй заказ и событие OrderCreated. Проверь сбой после commit, но до publish, повторную доставку и дедупликацию consumer.','Какой паттерн связывает запись в БД и последующую публикацию события?',['Transactional outbox','Случайная задержка','Глобальная переменная'],0,refs.py,35),
lesson('SLO, error budget и эксплуатационная зрелость','Переводить ожидания надёжности в измеримые эксплуатационные решения.','SLI измеряет пользовательский аспект сервиса; SLO задаёт целевое значение за период; SLA — внешнее обязательство с последствиями. Error budget — допустимая доля плохих событий. Если бюджет исчерпывается, команда может замедлить поставку функций и сосредоточиться на надёжности. Метрика должна отражать реальный пользовательский опыт.','99.9% успешных запросов за 30 дней — SLO только при чётком определении успешного запроса, окна и исключений.','Определи SLI/SLO для API: availability, latency p95, freshness. Рассчитай error budget и опиши policy для релизов при его расходовании.','Что задаёт SLO?',['Целевой уровень измеримого качества сервиса','Юридическое соглашение с клиентом всегда','Количество строк кода в релизе'],0,refs.py,30)
);
englishLessons.push(
lesson('A1 · Can и can’t для способностей','Говорить о простых навыках и возможностях.','Can не изменяется по лицам и используется с базовой формой глагола без to. Отрицание — cannot/can’t; вопрос строится перестановкой can и подлежащего. Для умения в прошлом часто используется could, но для единичного успешного действия возможна конструкция was able to.','She can swim. Can you drive? I can’t speak Japanese.','Напиши 8 предложений о своих навыках и задай партнёру пять вопросов с can.','Как правильно?',['He can to swim.','He can swim.','He cans swim.'],1,refs.en,15),
lesson('A1 · Объекты и местоимения дополнения','Использовать me, him, her, us и them после глаголов и предлогов.','Object pronouns занимают позицию дополнения: I know him; She called us. Они отличаются от subject pronouns (he/him, we/us). После предлогов также используется объектная форма: for me, with them. Не ставь объектное местоимение на место подлежащего.','They invited her, not she. This message is for you.','Преобразуй 10 предложений, заменяя повторяющиеся имена объектными местоимениями. Проверь позицию после предлогов.','Как правильно сказать «Я вижу их»?',['I see they.','I see them.','Me see they.'],1,refs.en,15),
lesson('A2 · Present Continuous для временных ситуаций','Описывать действия и ситуации, происходящие сейчас или в ограниченный период.','Present Continuous строится как am/is/are + verb-ing. Он описывает действие в момент речи, временную ситуацию вокруг настоящего периода и заранее организованную договорённость. Глаголы состояния обычно не используются в continuous в базовом значении, хотя возможны контекстные исключения.','I’m working from home this week. She is talking on the phone now.','Опиши текущую неделю в 10 предложениях, противопоставляя постоянные привычки и временные ситуации.','Как правильно?',['They are study now.','They are studying now.','They studying now.'],1,refs.en,18),
lesson('A2 · Some, any, much, many и a lot of','Выбирать количественные слова по типу существительного и типу предложения.','Some часто используется в утверждениях и предложениях; any — в вопросах и отрицаниях, но возможны исключения по смыслу. Much относится к неисчисляемым, many — к исчисляемым во множественном числе. A lot of подходит обоим типам и часто естественнее в разговорной речи.','There are many books, but not much time. Would you like some tea?','Составь список покупок и диалог в магазине, используя все пять выражений и минимум четыре вопроса.','Как правильно?',['many water','much water','a few water'],1,refs.en,18),
lesson('B1 · Wish и if only для сожалений и желаний','Выражать неудовлетворённость настоящим и сожаление о прошлом.','Wish + Past Simple описывает желание изменить настоящее; wish + Past Perfect — сожаление о прошлом. Wish + would часто выражает раздражение из-за поведения или желание изменения, которое воспринимается как контролируемое извне. If only усиливает эмоциональный акцент.','I wish I had more time. I wish I had studied earlier. I wish it would stop raining.','Напиши шесть предложений: два о настоящем, два о прошлом и два о раздражающем поведении. Объясни временную перспективу.','Как выразить сожаление о прошлом?',['I wish I studied yesterday.','I wish I had studied yesterday.','I wish I would studied yesterday.'],1,refs.en,20),
lesson('B1 · Пассивные конструкции с reporting verbs','Передавать распространённые мнения и сообщения в нейтральном формальном стиле.','Сочетания It is said that… и He is believed to… позволяют сообщать о распространённом мнении, не называя конкретный источник. Важно не превращать слух в установленный факт: указывай источник и степень достоверности, если это существенно. Временная форма инфинитива может показывать одновременность или предшествование.','The company is believed to be expanding. The device is reported to have failed during testing.','Преобразуй восемь сообщений с say, believe, report и expect. Добавь оговорку о качестве источника для трёх примеров.','Какой вариант корректен?',['He is believed to have left.','He believed to has left.','He is believe leave.'],0,refs.en,22),
lesson('B2 · Инверсия в условных предложениях','Использовать формальную инверсию без if в гипотетических конструкциях.','В формальном английском if можно опустить при инверсии: Had I known… (If I had known…), Were I to choose… (If I were to choose…), Should you need… (If you should need…). Такие конструкции характерны для письменной и официальной речи; в разговоре обычные if-clause чаще естественнее.','Had the team tested the migration, the outage might have been avoided.','Перепиши девять условных предложений в инвертированную форму и отметь, какие звучат слишком формально для повседневного разговора.','Какой вариант соответствует If I had known?',['Had I known','Have I knew','Did I had known'],0,refs.en,22),
lesson('B2 · Предлоги в сложных устойчивых сочетаниях','Повышать точность письменной речи через управление и collocations.','Многие прилагательные и глаголы требуют определённых предлогов: responsible for, interested in, comply with, account for. Предлог часто нельзя предсказать дословным переводом. Запоминай сочетание целиком с примером и типичным дополнением; проверяй значение в словаре при смене контекста.','The team is responsible for deployment; the service complies with the policy; the result depends on the sample.','Создай тематический глоссарий из 20 сочетаний для технологий и бизнеса. Напиши контекстные примеры и мини-тест на выбор предлога.','Какое сочетание корректно?',['comply to the policy','comply with the policy','comply at the policy'],1,refs.en,22),
lesson('C1 · Аргументация с counterargument и rebuttal','Строить убедительный аргумент, честно представляя сильнейшее возражение.','Сильный аргумент не игнорирует противоположную позицию. Counterargument формулирует разумное возражение, concession признаёт его часть, rebuttal показывает пределы или отвечает доказательствами. Не подменяй возражение слабой карикатурой (straw man). Разделяй эмпирические и нормативные разногласия.','Although the proposal reduces cost, its reliability risk is material; this can be mitigated through staged rollout and rollback criteria.','Напиши 300 слов по спорной рабочей теме: тезис, сильное возражение, concession, rebuttal, evidence и ограничение вывода.','Что отличает честный counterargument?',['Он представляет сильную версию противоположной позиции','Он намеренно упрощает мнение оппонента','Он заменяет доказательства эмоциональной оценкой'],0,refs.en,30),
lesson('C1 · Корпусная проверка коллокаций и регистра','Использовать словари и корпуса для проверки естественности, а не полагаться только на интуицию.','Корпуса показывают реальные контексты, частотность и типичные соседства слов. Сравнивай жанр, регион и период; высокая частота не гарантирует уместность в конкретной ситуации. Словари дают значения и пометы регистра, а корпус помогает увидеть шаблоны употребления.','Commit a crime и make a decision — устойчивые сочетания; для редкого термина проверь concordance lines в подходящем корпусе.','Проверь 12 сомнительных сочетаний в двух словарях и корпусе. Запиши значение, регистр, типичное окружение и пример.','Что важно учитывать при анализе корпусной частотности?',['Жанр, регион и контекст употребления','Только абсолютное число совпадений','Только личное предпочтение автора'],0,refs.en,25),
lesson('C2 · Редактура экспертного текста: точность и экономия','Редактировать текст на уровне аргумента, структуры, синтаксиса и лексики.','Экспертная редактура начинается с логики: тезис, основания, ограничения, вывод. Затем проверяются референция, параллелизм, коллокации, пунктуация и регистр. Удаляй повтор, если он не выполняет функцию связности или акцента. Не сокращай оговорку, которая меняет силу доказательства.','A substantial reduction in latency was observed under the tested workload точнее, чем The system is much faster, если вывод ограничен конкретной нагрузкой.','Отредактируй экспертный текст на 400 слов в два прохода: сначала аргумент и структура, затем стиль и точность. Подготовь список существенных изменений.','Что нельзя удалять ради краткости?',['Оговорку, необходимую для корректной интерпретации результата','Повтор одного и того же вводного слова','Избыточное прилагательное без смысловой нагрузки'],0,refs.en,30),
lesson('C2 · Переговорный дискурс и управление позицией','Формулировать условия, уступки и обязательства с высокой прагматической точностью.','Переговорная речь различает позицию, интерес, условие и обязательство. Формулы subject to, provided that, unless, to the extent that ограничивают область соглашения. Неоднозначные модальные слова могут создавать разные ожидания относительно обязательности. Уточняй сроки, владельцев и критерии исполнения.','We can proceed provided that the security review is completed by Friday устанавливает условие, а не безусловное обещание.','Смоделируй переговоры о сроках проекта: сформулируй предложение, условие, уступку, резервную позицию и итоговое обязательство без двусмысленности.','Что выражает provided that?',['Условие, при котором действует предложение','Причину уже произошедшего события','Безусловную гарантию результата'],0,refs.en,30)
);


/* Curated content batch 6 — reliability, platform strategy and advanced language use. */
jsLessons.push(
lesson('Principal-level платформенная стратегия и paved roads','Снижать стоимость разработки для нескольких команд через стандартизированные платформенные возможности.','Платформа должна уменьшать когнитивную нагрузку команд и повышать надёжность, а не превращаться в обязательный слой бюрократии. Paved road предлагает проверенный путь с безопасными defaults, документацией, шаблонами и измеримой поддержкой. Исключения допустимы, если альтернативный путь обоснован и не создаёт неприемлемый риск.','Единый шаблон сервиса с наблюдаемостью, CI, секретами и безопасным деплоем позволяет командам не собирать инфраструктуру заново.','Составь стратегию платформы для пяти продуктовых команд: пользовательские проблемы, paved roads, adoption metrics, migration path, ownership и exit criteria.','Что является главным результатом платформенной команды?',['Снижение совокупной стоимости и риска доставки для продуктовых команд','Максимальное число обязательных внутренних инструментов','Запрет на архитектурные исключения'],0,refs.js,35),
lesson('Распределённые системы: согласованность и идемпотентность','Выбирать модель согласованности и проектировать безопасные повторные операции.','Распределённая система сталкивается с задержками, частичными отказами и разделением сети. Strong consistency упрощает чтение актуального состояния ценой доступности/латентности в некоторых топологиях; eventual consistency требует обработки временно расходящихся представлений. Идемпотентная команда даёт одинаковый итог при повторном применении в пределах заданного ключа и окна.','Запрос создания заказа с idempotency key возвращает тот же результат при сетевом retry, не создавая второй заказ.','Спроектируй команду оплаты с сетевыми таймаутами, повторной доставкой, idempotency key, журналом операций и reconciliation-процессом.','Что защищает от повторного создания заказа при retry клиента?',['Идемпотентный ключ с серверной дедупликацией','Увеличение таймаута клиента','Случайная задержка перед повтором'],0,refs.js,35),
lesson('Chaos engineering и проверка отказоустойчивости','Проверять гипотезы о поведении системы при контролируемых отказах.','Chaos engineering — дисциплина экспериментов с отказами в ограниченном радиусе воздействия. Сначала формулируется steady state и гипотеза, затем вводится контролируемый сбой, измеряется результат и проверяется восстановление. Нельзя запускать разрушительные эксперименты без согласованной среды, blast-radius limits и rollback.','Отключение одного тестового upstream в staging проверяет, срабатывают ли timeout, circuit breaker и fallback.','Подготовь безопасный chaos experiment: гипотеза, baseline, fault injection, scope, abort conditions, наблюдаемость и postmortem.','Что должно быть определено до fault injection?',['Steady state, предел воздействия и условия остановки','Только название эксперимента','План удаления всех резервных копий'],0,refs.js,35),
lesson('Circuit breaker, bulkhead и graceful degradation','Защищать сервис от каскадных отказов и перегрузки зависимостей.','Circuit breaker временно прекращает вызовы отказавшей зависимости, переходя между closed, open и half-open. Bulkhead изолирует ресурсы, чтобы перегрузка одной подсистемы не вытеснила остальные. Graceful degradation сохраняет ключевую функцию с ограниченным качеством, если второстепенная зависимость недоступна.','Рекомендации могут временно отключиться при сбое сервиса рекомендаций, сохранив основной сценарий покупки.','Спроектируй отказоустойчивость для API с двумя зависимостями. Определи timeout, threshold, recovery probe, resource pools и пользовательский fallback.','Какую проблему решает bulkhead?',['Изоляцию ресурсов и ограничение распространения перегрузки','Шифрование сетевого трафика','Автоматическую миграцию базы данных'],0,refs.js,30),
lesson('Технический due diligence и стоимость владения','Оценивать архитектуру через риски, эксплуатационные затраты и обратимость решений.','Технический due diligence исследует не только качество кода, но и операционные зависимости, безопасность, данные, лицензии, bus factor, стоимость инфраструктуры и скорость изменений. TCO включает разработку, эксплуатацию, поддержку, инциденты и миграции. Оценка должна отделять подтверждённые факты от гипотез и фиксировать confidence.','Сервис с низкой стоимостью хостинга может иметь высокий TCO из-за ручных релизов, частых инцидентов и зависимости от одного специалиста.','Подготовь due-diligence memo для небольшого SaaS: архитектура, безопасность, reliability, delivery, TCO, ключевые риски и план снижения риска на 90 дней.','Что обычно пропускает оценка, учитывающая только цену сервера?',['Поддержку, инциденты, миграции и стоимость изменений','Только размер HTML-файла','Цветовую схему интерфейса'],0,refs.js,35),
lesson('Distinguished Engineer: техническое видение на несколько лет','Формировать долгосрочное техническое направление с проверяемыми ставками и этапами пересмотра.','Техническое видение описывает будущие возможности, ограничения, стратегические ставки и последовательность перехода. Оно не должно быть неизменяемым прогнозом: задаются leading indicators, checkpoints и условия пересмотра. Влияние Distinguished Engineer проявляется в улучшении решений нескольких организаций и экосистем, а не только в авторстве сложного кода.','Стратегия миграции на event-driven платформу может начинаться с одного bounded context, измерять latency и операционную нагрузку, затем расширяться при подтверждении выгод.','Напиши трёхлетнее техническое видение: текущие ограничения, целевые capabilities, 3 ставки, альтернативы, этапы, метрики, обратимые эксперименты и критерии остановки.','Что делает долгосрочное техническое видение ответственным?',['Проверяемые гипотезы и заранее заданные критерии пересмотра','Уверенное обещание точных результатов на три года','Отсутствие альтернативных сценариев'],0,refs.js)
);
pyLessons.push(
lesson('Python packaging: pyproject и воспроизводимые сборки','Оформлять пакет с явными метаданными, зависимостями и воспроизводимой сборкой.','pyproject.toml является стандартной точкой конфигурации сборки и инструментов. Build backend определяет процесс сборки; runtime dependencies отделяются от dev dependencies. Lock-файл фиксирует разрешённый набор зависимостей для приложения, но библиотека обычно объявляет совместимые диапазоны. Проверяй wheel и sdist в чистой среде.','python -m build создаёт дистрибутивы; установка wheel в отдельное окружение проверяет, что пакет не зависит от файлов рабочей директории.','Упакуй библиотеку с pyproject.toml, type hints, тестами и CI. Собери wheel/sdist и проверь установку из артефакта в чистом окружении.','Что проверяет установка из собранного wheel?',['Что пакет самодостаточен вне исходной рабочей директории','Что все тесты автоматически успешны','Что зависимости не нужны'],0,refs.py,30),
lesson('Supply-chain security Python-зависимостей','Снижать риск компрометации через зависимости и артефакты сборки.','Риски цепочки поставок включают typosquatting, захваченные аккаунты, вредоносные релизы и компрометацию build pipeline. Используй минимальные зависимости, проверяй происхождение пакетов, фиксируй версии и хэши там, где уместно, сканируй уязвимости и ограничивай секреты CI. SBOM помогает видеть состав поставки, но не гарантирует безопасность.','Lock с hashes повышает воспроизводимость установки; обновления всё равно требуют review changelog и тестирования.','Составь pipeline: dependency review, lock/hash verification, vulnerability scan, SBOM, isolated build и secret scanning. Определи policy исключений.','Что даёт SBOM?',['Инвентаризацию компонентов и зависимостей','Гарантию отсутствия уязвимостей','Автоматическую замену всех библиотек'],0,refs.py,30),
lesson('Безопасная сериализация и десериализация','Не исполнять недоверенные данные и контролировать формат обмена.','pickle может выполнять произвольный код при десериализации и не подходит для недоверенных данных. JSON безопаснее в смысле отсутствия встроенного механизма выполнения кода, но всё равно требует schema validation, лимитов размера и защиты от resource exhaustion. Для криптографической целостности нужна отдельная проверка подписи или MAC.','json.loads загружает структуру данных, после чего валидатор проверяет типы, обязательные поля и допустимые диапазоны.','Разбери угрозы для endpoint импорта пользовательских файлов. Реализуй JSON schema validation, лимит размера, отказ на неожиданных типах и тесты вредоносных payload.','Почему опасно вызывать pickle.loads на недоверенном вводе?',['Десериализация может выполнить произвольный код','pickle принимает только строки UTF-8','pickle автоматически шифрует объект'],0,refs.py,30),
lesson('Нагрузочное тестирование и capacity planning','Оценивать пределы системы по профилю нагрузки и целевым SLO.','Load test моделирует ожидаемую нагрузку; stress test ищет предел; spike test проверяет резкий скачок; soak test выявляет деградацию со временем. Capacity planning учитывает concurrency, throughput, latency, saturation и headroom. Результат без реалистичного профиля запросов и окружения малоценен.','Рост latency p95 при стабильном CPU может указывать на ожидание пула соединений или внешней зависимости.','Определи профиль нагрузки API, проведи baseline, ramp, spike и soak в тестовой среде. Построй capacity model и предложи безопасный запас.','Что помогает выявить утечку ресурсов со временем?',['Soak test','Только один короткий smoke test','Проверка форматирования кода'],0,refs.py,35),
lesson('Резервное копирование и disaster recovery','Определять RPO/RTO и регулярно проверять восстановление данных.','RPO задаёт допустимую потерю данных по времени; RTO — целевое время восстановления сервиса. Наличие backup не доказывает возможность восстановления: нужны проверяемые копии, контроль доступа, шифрование, retention и регулярные restore drills. План DR включает зависимости, владельцев и коммуникации.','Ежедневная резервная копия с RPO 24 часа не удовлетворит требованию потери данных не более пяти минут.','Составь DR plan для приложения с БД и файловым хранилищем. Определи RPO/RTO, частоту backup, проверку restore, роли и порядок переключения.','Что измеряет RPO?',['Максимально допустимую потерю данных во времени','Время полного восстановления сервиса','Число пользователей в очереди'],0,refs.py,30),
lesson('Principal-level инженерная стратегия Python-платформы','Выбирать общие стандарты и платформенные инвестиции на основе стоимости изменений и риска.','Стратегия языка в организации должна учитывать версии runtime, совместимость библиотек, packaging, typing, observability, security и обучение команд. Централизация снижает фрагментацию, но чрезмерные ограничения тормозят команды. Устанавливай поддерживаемую матрицу версий, migration windows и механизм исключений.','Общая библиотека логирования оправдана, если она стабилизирует формат событий и снижает стоимость интеграции, а не просто скрывает API стандартного logging.','Разработай Python platform RFC для 20 сервисов: версии, packaging, typing policy, security gates, migration roadmap, ownership и измерение adoption.','Какой компромисс нужно явно учитывать при стандартизации платформы?',['Единообразие против автономии и скорости команд','Размер отступа против цвета IDE','Наличие комментариев против названий файлов'],0,refs.py,35)
);
englishLessons.push(
lesson('A1 · Imperatives и инструкции','Давать простые команды и инструкции в повседневных ситуациях.','Imperative использует базовую форму глагола без подлежащего: Open the door. Для вежливости добавляй please. Отрицательная форма строится с don’t: Don’t touch that. Let’s + verb предлагает совместное действие. Интонация и контекст определяют, звучит ли команда резко или нейтрально.','Please turn left. Don’t open the window. Let’s start now.','Напиши инструкцию из 8 шагов для простого действия и добавь три предупреждения с don’t.','Как правильно запретить вход?',['Not enter!','Don’t enter!','Doesn’t enter!'],1,refs.en,15),
lesson('A1 · Даты, порядковые числительные и возраст','Называть даты, этажи и возраст в типичных форматах.','Порядковые числительные first, second, third, fourth используются для дат и порядка. В британском английском дата часто произносится day–month; в американском month–day. Возраст выражается be + число: She is 16, а не has 16. Год читается по распространённым моделям, зависящим от числа.','My birthday is on the third of May. He is sixteen years old.','Запиши и проговори 10 дат, пять этажей и пять возрастов. Проверь различия формата дат UK/US.','Как правильно сказать «Ей 18 лет»?',['She has 18 years.','She is 18.','She does 18.'],1,refs.en,15),
lesson('A2 · Past Continuous и фоновые события','Описывать длительное действие, на фоне которого произошло короткое событие.','Past Continuous строится was/were + verb-ing. Он задаёт процесс в определённый момент прошлого или фон для другого действия. Past Simple часто описывает событие, которое произошло на этом фоне. While часто сопровождает длительный процесс, when — момент события, но это не жёсткое правило.','I was reading when the phone rang. While they were walking, it started to rain.','Напиши рассказ из 120 слов с четырьмя фоновыми действиями и четырьмя событиями, которые их прерывают.','Какое предложение корректно?',['I was sleep when he called.','I was sleeping when he called.','I slept when he was call.'],1,refs.en,18),
lesson('A2 · Too, enough и so/such','Выражать степень качества и достаточность.','Too + adjective означает чрезмерную степень; adjective + enough — достаточную степень; enough + noun — достаточное количество. So + adjective/adverb и such + noun phrase усиливают характеристику. Следи за порядком слов и за тем, что too часто несёт негативный оттенок.','The box is too heavy to lift. The room is big enough for us. It was such a useful lesson.','Составь 10 предложений о проблемах и решениях, используя too, enough, so и such.','Как правильно?',['The coffee is enough hot.','The coffee is hot enough.','The coffee too enough hot.'],1,refs.en,18),
lesson('B1 · Future Continuous и Future Perfect','Описывать процесс и завершённость к определённому моменту в будущем.','Future Continuous (will be + -ing) показывает действие в процессе в будущем моменте. Future Perfect (will have + past participle) показывает завершённость к будущему сроку. By часто указывает на дедлайн, this time next week — момент процесса.','This time tomorrow I will be travelling. By Friday, we will have finished the report.','Опиши свой проект на следующей неделе: пять процессов в конкретный момент и пять результатов, завершённых к сроку.','Какое время уместно для «К пятнице мы закончим»?',['Future Perfect','Past Continuous','Present Perfect Continuous'],0,refs.en,20),
lesson('B1 · Артикли в обобщениях и институциональных названиях','Выбирать нулевой артикль, the и a/an в более сложных контекстах.','Нулевой артикль часто используется при обобщениях во множественном числе и неисчисляемых понятиях: Computers are useful; Information matters. The может обозначать конкретный класс или уникально определённый объект; названия учреждений имеют устойчивые модели, которые нужно проверять по словарю.','Education is important (понятие в общем смысле); the education I received was valuable (конкретный опыт).','Отредактируй 15 предложений с обобщениями, конкретными ссылками и названиями организаций. Объясни каждый артикль.','Как обычно говорят обобщённо?',['The computers are useful всегда','Computers are useful','A computers are useful'],1,refs.en,20),
lesson('B2 · Participle clauses и сокращённые придаточные','Сокращать придаточные предложения, сохраняя ясную связь субъекта.','Participle clauses позволяют компактно выразить время, причину или сопутствующее действие. Действующий субъект должен совпадать с субъектом главного предложения, иначе возникает dangling participle. Perfect participle показывает предшествование: Having completed the review, the team approved the change.','Having checked the figures, Maria sent the report — Maria выполнила обе последовательные операции.','Сократи десять придаточных предложений в participle clauses. Найди и исправь dangling modifiers.','В чём ошибка dangling participle?',['Причастная конструкция логически относится не к тому субъекту','Всегда используется Past Simple','В предложении отсутствует артикль'],0,refs.en,22),
lesson('B2 · Subjunctive и формальные рекомендации','Использовать формальные конструкции требования, рекомендации и необходимости.','В формальном английском mandative subjunctive использует базовую форму глагола после suggest, recommend, insist и некоторых прилагательных: They recommended that he be present. В британском варианте часто встречается should + infinitive. Выбор зависит от регистра и региональной нормы.','The committee insisted that the report be revised.','Перепиши 10 рекомендаций и требований в двух вариантах: subjunctive и should-construction. Укажи регистр и смысл.','Какой вариант соответствует mandative subjunctive?',['They suggested that he be informed.','They suggested that he is informed yesterday.','They suggested him to be informed always.'],0,refs.en,22),
lesson('C1 · Метафора и фрейминг в профессиональной коммуникации','Распознавать, как метафорический выбор меняет интерпретацию проблемы.','Метафоры структурируют абстрактные идеи: backlog как очередь, стратегия как карта, риск как экспозиция. Фрейминг влияет на внимание и оценку, но может скрывать альтернативы. В профессиональном тексте метафора должна прояснять модель, а не подменять количественное описание или доказательство.','Describing debt as technical debt highlights future maintenance cost, but may obscure organizational causes if used as the only frame.','Проанализируй три метафоры в деловом тексте: какой аспект они выделяют, что скрывают и какая нейтральная формулировка точнее.','Что является риском чрезмерного фрейминга?',['Он может скрывать альтернативные аспекты проблемы','Он автоматически делает утверждение истинным','Он устраняет необходимость данных'],0,refs.en,25),
lesson('C1 · Устная презентация сложных данных','Объяснять графики и неопределённость аудитории без искажения статистики.','Описание данных должно различать абсолютные значения, относительные изменения, базу сравнения и неопределённость. Не называй небольшое изменение «резким» без масштаба; не выводи причинность из простой временной динамики. Хорошая устная презентация сначала сообщает вывод, затем доказательство и ограничение.','Revenue rose by 8% from a small baseline; абсолютное изменение и период помогают оценить значимость.','Подготовь 4-минутный доклад по графику: главный вывод, масштаб, сравнение, uncertainty, ограничение и ответ на критический вопрос.','Что нужно сообщить при заявлении «рост на 50%»?',['Базу сравнения и абсолютный масштаб','Только процент без контекста','Только цвет линии на графике'],0,refs.en,25),
lesson('C2 · Перевод юмора и культурных аллюзий','Сохранять функцию юмора и аллюзии, когда дословный перенос не работает.','Юмор зависит от ожиданий, двусмысленности, культурного знания и ритма. При адаптации выбирай между сохранением аллюзии, функциональным аналогом, пояснением и компенсацией в другом месте. Не каждый каламбур можно сохранить без потери тона; решение зависит от жанра и аудитории.','В субтитрах короткая функциональная замена иногда лучше буквального объяснения, которое разрушает темп шутки.','Адаптируй три примера wordplay для субтитров, корпоративного выступления и литературного перевода. Обоснуй компромисс в каждом случае.','Какой принцип важнее при адаптации юмора?',['Сохранить коммуникативную функцию с учётом аудитории','Всегда переводить каждое слово буквально','Добавлять объяснение после каждой шутки'],0,refs.en,30),
lesson('C2 · Экспертная дискуссия: уточнение и repair','Управлять недопониманием и корректировать формулировку в реальном времени.','Repair в разговоре включает self-initiated self-repair, просьбу уточнить и переформулирование. Экспертная дискуссия требует различать несогласие с тезисом и непонимание термина. Уточняющие вопросы должны быть конкретными: определить термин, масштаб, допущение или причинную связь.','When you say “efficient”, do you mean lower latency, reduced cost, or both? уточняет критерий вместо преждевременного спора.','Запиши сценарий экспертной дискуссии на 5 минут: три уточнения, два self-repair, одно переформулирование позиции и корректное резюме оппонента.','Какой вопрос лучше уточняет неоднозначный термин?',['What exactly do you mean by efficient in this context?','You are wrong.','Why is your wording bad?'],0,refs.en)
);


/* Curated content batch 7 — governance, security engineering and proficiency consolidation. */
jsLessons.push(
lesson('Threat modeling frontend и API: STRIDE','Систематически находить угрозы по активам, границам доверия и потокам данных.','Threat modeling начинается с активов, субъектов, trust boundaries и data-flow diagram. STRIDE классифицирует Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service и Elevation of Privilege. Модель должна приводить к проверяемым mitigations и тестам, а не к длинному списку абстрактных рисков.','Пользовательский ввод проходит браузер, API gateway, backend и хранилище; на каждой границе проверяются аутентификация, авторизация, валидация и журналирование.','Построй DFD для авторизации и сохранения профиля. Для каждой границы найди STRIDE-угрозу, риск, mitigation и тест, который доказывает защиту.','Что является первым шагом полезного threat modeling?',['Определить активы, границы доверия и потоки данных','Сразу выбрать библиотеку шифрования','Перечислить все известные CVE без контекста'],0,refs.js,35),
lesson('OAuth/OIDC и безопасная работа с токенами','Различать authentication и authorization и безопасно обрабатывать токены.','OAuth 2.0 делегирует доступ; OpenID Connect добавляет слой аутентификации и ID Token. Access token предназначен для доступа к API, ID token сообщает сведения об аутентификации клиента. Проверяй issuer, audience, signature, expiry, nonce/state в соответствующем потоке. Не храни секреты в публичном frontend и не путай JWT с гарантией безопасности.','Authorization Code Flow с PKCE подходит public clients; state защищает связывание запроса и ответа, PKCE снижает риск перехвата authorization code.','Разбери поток OIDC для SPA и backend. Определи места проверки issuer/audience/nonce, хранение токенов, CSRF-риск и безопасный logout.','Для чего нужен PKCE в public client?',['Связать authorization code с инициировавшим клиентом и снизить риск перехвата','Зашифровать весь HTTP-трафик','Заменить проверку issuer и audience'],0,refs.js,35),
lesson('Supply-chain security frontend','Управлять риском npm-зависимостей и воспроизводимостью сборки.','Зависимость может быть скомпрометирована через maintainer account, lifecycle script, typosquatting или transitives. Lockfile фиксирует разрешённое дерево, но не гарантирует отсутствие вредоносного кода. Минимизируй зависимости, контролируй install scripts, проверяй происхождение артефактов, применяй SBOM и обновляйся через review и тесты.','npm ci использует lockfile для воспроизводимой установки; CI должен работать с минимальными permissions и без production secrets на непроверенных pull requests.','Составь supply-chain checklist для frontend CI: lockfile, audit policy, SBOM, provenance, script controls, token permissions и dependency update workflow.','Что гарантирует lockfile?',['Фиксацию дерева разрешённых версий, но не безопасность самих пакетов','Отсутствие уязвимостей во всех зависимостях','Что каждый пакет написан доверенным автором'],0,refs.js,30),
lesson('Data consistency в offline-first приложении','Проектировать синхронизацию локальных изменений с сервером при конфликте и повторной доставке.','Offline-first требует локального источника доступности и явной модели синхронизации. Каждая операция должна иметь стабильный ID, время/версию, автора и идемпотентный серверный контракт. Last-write-wins прост, но может терять изменения; optimistic concurrency обнаруживает конфликт; CRDT подходят только для определённых типов данных и не устраняют все продуктовые решения.','Локальная запись хранит operationId и baseVersion; сервер применяет операцию один раз или возвращает conflict для разрешения.','Спроектируй синхронизацию заметок на двух устройствах: offline edits, повторная отправка, конфликт версий, удаление и восстановление. Определи тесты гонок.','Почему нельзя полагаться только на timestamp устройства для разрешения конфликтов?',['Часы устройств могут расходиться и не задают надёжный глобальный порядок','Timestamp всегда скрывает персональные данные','Сервер не умеет хранить даты'],0,refs.js,35),
lesson('Архитектурные метрики и fitness functions','Автоматизировать проверку архитектурных инвариантов в CI.','Fitness function — автоматическая проверка свойства архитектуры: границы модулей, запрет циклических зависимостей, бюджет bundle, latency или политика безопасности. Метрика должна отражать полезное свойство и иметь понятное действие при нарушении. Набор проверок следует пересматривать, чтобы не закреплять устаревшие ограничения.','CI может отклонять изменение, которое добавляет запрещённую зависимость между domain и UI слоями.','Выбери пять архитектурных инвариантов проекта и реализуй fitness checks: критерий, инструмент, порог, исключение и владелец.','Что проверяет fitness function?',['Измеримое архитектурное свойство на постоянной основе','Только стиль комментариев','Личное мнение ревьюера без критерия'],0,refs.js,30),
lesson('Техническая стратегия и управление портфелем рисков','Распределять инженерные инвестиции между ростом, надёжностью и сокращением долга.','Технический портфель включает product bets, reliability work, security, platform investments и обязательное обслуживание. Приоритизация учитывает expected value, вероятность, стоимость задержки, обратимость и корреляцию рисков. Нельзя ранжировать инициативы только по краткосрочному ROI: некоторые работы снижают системный риск и сохраняют опциональность.','Risk register связывает риск с владельцем, leading indicator, mitigation, residual risk и review date.','Собери квартальный инженерный портфель из десяти инициатив. Обоснуй баланс инвестиций, зависимости, capacity allocation и критерии пересмотра.','Что помогает управлять системным риском портфеля?',['Явный risk register с владельцами и сигналами пересмотра','Распределение всего времени только на новые функции','Оценка задач только по числу строк кода'],0,refs.js)
);
pyLessons.push(
lesson('Python security: subprocess и безопасное выполнение команд','Избегать command injection и контролировать дочерние процессы.','subprocess с аргументами-списком и shell=False снижает риск интерпретации пользовательского ввода оболочкой. Не передавай недоверенные строки в shell=True. Ограничивай timeout, окружение, рабочую директорию и права процесса; проверяй код возврата и объём вывода.','subprocess.run(["tool","--input",validated_path], check=True, timeout=10, capture_output=True, text=True) задаёт более контролируемый контракт.','Реализуй обёртку запуска внешнего инструмента. Добавь тесты на пробелы в путях, timeout, ненулевой exit code и попытку shell injection.','Какой подход безопаснее для обычного запуска команды?',['Передавать список аргументов с shell=False','Конкатенировать пользовательский ввод в shell-команду','Отключить проверку exit code'],0,refs.py,30),
lesson('Python observability: структурные логи и tracing','Связывать события одного запроса через trace context и структурированные поля.','Структурный лог хранит поля отдельно от форматированной строки: event, severity, request_id, trace_id и outcome. Не логируй секреты. Distributed tracing связывает spans между сервисами через trace context; sampling помогает контролировать стоимость. Метрики агрегируют поведение, логи объясняют отдельные события, traces показывают путь запроса.','logger.info("payment_authorized", extra={"request_id": request_id, "provider": provider}) предпочтительнее конкатенации неструктурированной строки.','Добавь структурное логирование и trace propagation в учебный API. Проверь correlation id через два сервиса и redaction токенов.','Что связывает spans одного распределённого запроса?',['Trace context и trace ID','Имя Python-файла','Один глобальный print'],0,refs.py,30),
lesson('Миграции схемы БД без простоя','Выполнять изменения схемы с обратной совместимостью нескольких версий приложения.','Безопасная миграция часто использует expand-and-contract: добавить новое поле/таблицу, поддержать двойное чтение или запись, backfill, переключить потребителей и только после проверки удалить старое. Миграции должны быть наблюдаемыми, повторяемыми и иметь план остановки. Большие backfill операции выполняются пакетами с контролем нагрузки.','Сначала приложение пишет в старое и новое поле, затем проверяется паритет данных, после чего чтение переключается на новое.','Спроектируй миграцию большой таблицы: schema expansion, backfill batches, dual-write, verification queries, cutover и contract phase.','Почему опасно удалить старое поле в одном релизе одновременно с изменением кода?',['Старые экземпляры приложения ещё могут читать или писать это поле','Потому что SQL не поддерживает удаление столбцов','Потому что миграции всегда выполняются только ночью'],0,refs.py,35),
lesson('Feature flags и контроль постепенного rollout','Выпускать функциональность поэтапно и управлять сроком жизни флагов.','Feature flag отделяет deployment от release. Rollout можно ограничить процентом пользователей, сегментом или средой; метрики и guardrails определяют расширение или откат. Флаги создают технический долг и ветвления, поэтому у каждого должны быть owner, purpose, expiry и план удаления.','Canary rollout начинает с малого сегмента, сравнивает error rate и latency с control group, затем расширяется при соблюдении guardrails.','Спроектируй rollout новой формы оплаты с флагом, сегментами, метриками, rollback threshold, kill switch и датой удаления флага.','Что предотвращает накопление постоянных feature flags?',['Владелец, срок действия и задача удаления','Добавление новых условий в каждый модуль','Отсутствие документации'],0,refs.py,30),
lesson('Python performance: алгоритмы, vectorization и native code','Выбирать оптимизацию по профилю и стоимости передачи данных.','Сначала оцени сложность алгоритма и профилируй горячий участок. Векторизация NumPy переносит циклы в оптимизированный native code, но конвертация данных и выделение массивов имеют цену. C extensions и JIT могут помочь при устойчивом узком месте, но увеличивают сложность сборки и сопровождения.','Операция над массивом NumPy может быть быстрее Python-цикла на больших данных, но медленнее для крошечного набора из-за overhead.','Сравни Python loop, NumPy и альтернативный алгоритм на малых и больших данных. Измерь runtime, память, warm-up и стоимость преобразования.','Что нужно проверить перед выбором vectorization?',['Размер данных и overhead преобразования наряду с профилем','Только количество символов в исходнике','Только скорость одного случайного запуска'],0,refs.py,30),
lesson('Distinguished Python Engineer: управление эволюцией экосистемы','Формировать устойчивую политику runtime, tooling и совместимости для большой организации.','На уровне организации важно управлять поддерживаемыми версиями Python, сроками обновлений, совместимостью нативных расширений, стандартами typing, packaging и security response. Эволюция экосистемы требует обратной связи команд, публичных RFC, миграционных инструментов и прозрачных исключений. Стандарт должен снижать риск, а не замораживать развитие.','Общий migration toolkit может автоматически находить deprecated API и готовить pull requests, сохраняя право команды контролировать выпуск.','Подготовь 2-летний roadmap Python ecosystem: runtime support matrix, tooling, security, migration automation, governance и измеримые adoption outcomes.','Что обеспечивает устойчивую эволюцию внутренней Python-платформы?',['Поддерживаемая матрица версий, migration tooling и прозрачное governance','Запрет на обновление runtime','Единый глобальный пакет без владельца'],0,refs.py,35)
);
englishLessons.push(
lesson('A1 · Like, love, hate + -ing','Говорить о предпочтениях и занятиях в свободное время.','Like, love и hate часто употребляются с герундием (-ing), когда речь о занятии в целом. Возможен и to-infinitive, особенно при привычке или выборе в конкретной ситуации. Для простого уровня полезно закрепить частотную модель like doing.','I like reading. She loves swimming. They hate waiting.','Составь 10 предложений о предпочтениях и проведи мини-опрос из пяти вопросов с What do you like doing?','Какой вариант грамматически естественен?',['I enjoy to read.','I like reading.','I likes reading.'],1,refs.en,15),
lesson('A1 · Наречия времени и последовательность дня','Описывать распорядок с first, then, after that и finally.','Маркеры последовательности помогают слушателю восстановить порядок действий. First вводит первый шаг, then/after that продолжают, finally закрывает последовательность. Наречия usually и sometimes уточняют частоту и обычно стоят перед смысловым глаголом.','First I get up, then I have breakfast. After that I go to school. Finally I do my homework.','Расскажи о своём обычном дне в 10 предложениях, используя минимум четыре маркера последовательности и три маркера частоты.','Какой маркер обычно завершает последовательность?',['Finally','Because','Although'],0,refs.en,15),
lesson('A2 · Relative pronouns who, which, that и where','Связывать предложения с помощью простых определительных придаточных.','Who обычно относится к людям, which — к предметам, that часто заменяет who/which в defining clauses, where — к месту. В non-defining clauses that не используется. Выбор относительного местоимения зависит от его функции внутри придаточной части.','The person who called you is my teacher. This is the café where we met.','Соедини 12 пар предложений через relative clauses и выдели слово, к которому относится придаточная часть.','Какое слово подходит для места?',['where','whose','who'],0,refs.en,18),
lesson('A2 · Present Perfect с ever, never, just, already и yet','Рассказывать об опыте и недавних событиях с типичными маркерами.','Ever часто используется в вопросах об опыте; never выражает отсутствие опыта; just — недавнее действие; already — действие, выполненное раньше ожидаемого; yet часто встречается в вопросах и отрицаниях. Yet обычно стоит в конце, just и already — между have/has и past participle.','Have you ever tried sushi? I have just finished. She hasn’t called yet.','Составь диалог о жизненном опыте и списке выполненных задач, используя все пять маркеров.','Где обычно стоит yet в Present Perfect?',['В конце предложения','Перед have','Между подлежащим и have всегда'],0,refs.en,18),
lesson('B1 · Инфинитив цели и конструкции purpose','Объяснять цель действия кратко и точно.','To-infinitive часто выражает цель: I called to ask a question. In order to и so as to звучат формальнее; отрицательная цель — in order not to / so as not to. So that вводит придаточное с собственным подлежащим и модальным глаголом, когда нужно явно показать результат или участника.','We left early to avoid traffic. I wrote it down so that I wouldn’t forget.','Переформулируй 10 предложений с разными конструкциями цели и объясни выбор регистра.','Как выразить цель «чтобы не опоздать»?',['to not late','in order not to be late','for not be late'],1,refs.en,20),
lesson('B1 · Союзы причины, результата и цели','Различать because, since, so, therefore и so that по логической функции.','Because вводит причину; so и therefore — результат; so that — цель или ожидаемый эффект. Since может означать причину или время, поэтому контекст важен. Не соединяй независимые предложения запятой без подходящего союза или пунктуации.','The server was unavailable, so we delayed the release. We delayed the release because the server was unavailable.','Свяжи 12 пар фактов, используя пять союзов. Для каждого укажи направление логической связи.','Какой союз обычно вводит причину?',['because','therefore','so that'],0,refs.en,20),
lesson('B2 · Дистанцирование автора и attribution','Точно отделять собственную позицию от позиции источника.','Attribution verbs задают отношение к источнику: claims может звучать дистанцированно, demonstrates предполагает сильное доказательство, suggests — более осторожный вывод, acknowledges отмечает ограничение. Выбор глагола должен соответствовать содержанию и качеству источника, а не служить скрытой оценкой автора.','The authors report an association; the analysis does not establish causation.','Напиши обзор трёх источников, используя разные attribution verbs. Проверь, что каждый глагол точно отражает силу утверждения.','Какой глагол осторожнее для предварительных данных?',['suggests','proves conclusively','guarantees'],0,refs.en,22),
lesson('B2 · Структура сложного аргументативного эссе','Строить эссе с последовательным тезисом, контраргументом и выводом.','Эффективное эссе формулирует позицию во введении, развивает отдельные основания в абзацах, использует доказательства и переходы, рассматривает контраргумент и завершает выводом, который отвечает на исходный вопрос. Связность не сводится к набору linking words: каждый абзац должен выполнять ясную функцию.','A paragraph can follow claim → evidence → analysis → link, but structure should adapt to genre and complexity.','Напиши эссе 350 слов по спорному вопросу. Проверь тезис, topic sentences, доказательства, контраргумент, переходы и вывод.','Что должно связывать абзац с общим тезисом?',['Его основная идея и доказательства','Только длинный список союзов','Обязательная цитата в каждом предложении'],0,refs.en,25),
lesson('C1 · Логические ошибки в публичной аргументации','Распознавать ошибочные выводы и объяснять, почему они не следуют из посылок.','Ad hominem атакует личность вместо аргумента; false dilemma исключает альтернативы; post hoc принимает последовательность за причинность; hasty generalization обобщает по малой выборке. Название ошибки не заменяет анализа: укажи посылки, вывод и конкретный разрыв логики.','После запуска функции метрика улучшилась — это ещё не доказывает, что улучшение вызвано именно функцией: могли измениться другие факторы.','Разбери восемь аргументов. Для каждого выдели посылки, вывод, возможную ошибку и недостающие данные.','Что является post hoc ошибкой?',['Считать событие причиной другого только потому, что оно произошло раньше','Атаковать личность оппонента','Представить две реальные альтернативы'],0,refs.en,25),
lesson('C1 · Редактирование неопределённости и количественных утверждений','Формулировать количественные выводы без ложной точности и преувеличения.','Проценты требуют знаменателя и периода; среднее — описания распределения; интервалы — определения метода и уровня доверия. Слова most, significant, substantial и negligible требуют контекста. Не называй статистическую значимость практической важностью и не скрывай диапазон неопределённости.','Median latency fell from 240 ms to 210 ms (12.5%) under the tested workload точнее, чем latency improved dramatically.','Отредактируй десять количественных утверждений: добавь базу, период, единицы и ограничение; убери ложную точность.','Что необходимо для интерпретации процента роста?',['База сравнения и абсолютный масштаб','Только округлённое число','Только прилагательное significant'],0,refs.en,25),
lesson('C2 · Стратегическое резюмирование для руководителей','Сжимать большой массив информации до решения, риска и требуемого действия.','Executive summary начинается с решения или ключевого вывода, затем даёт минимально достаточные основания, варианты, риски и запрашиваемое действие. Сохраняй различие между фактом, оценкой и рекомендацией. Сложность материала не оправдывает перегруженный текст: детали выносятся в приложение, но критические оговорки остаются видимыми.','Recommendation: delay rollout by one week; reason: unresolved data-loss risk; decision required: approve remediation capacity.','Сократи аналитический отчёт до 150 слов для руководителя: решение, два основания, риск, альтернативы и конкретный запрос.','Что должно быть ясно из хорошего executive summary?',['Какое решение требуется и почему','Все технические детали реализации','Только история проекта без вывода'],0,refs.en,25),
lesson('C2 · Сложные модальные оттенки и эпистемическая позиция','Точно различать необходимость, вероятность, обязательство и вывод.','Модальные средства выражают разные типы позиции: must может означать обязанность или сильный вывод; should — рекомендацию или ожидание; may/might — возможность; needn’t — отсутствие необходимости. Перфектная форма меняет временную перспективу и часто выражает вывод о прошлом. Контекст определяет интерпретацию.','You must have seen the notice — сильный вывод; You must see the notice — требование/необходимость в зависимости от контекста.','Подготовь пары минимальных контекстов для 10 модальных конструкций и объясни, как меняется смысл при смене времени и регистра.','Что обычно выражает must have + past participle в контексте дедукции?',['Сильный вывод о прошлом','Запрет в будущем','Отсутствие необходимости'],0,refs.en,30)
);


/* Curated continuation batch: reliability, data modelling, Python concurrency,
   and one incremental English skill per CEFR band. */
jsLessons.push(
lesson('JavaScript · Детерминированное управление временем и таймерами','Различать wall-clock time, monotonic time и планирование задач event loop.','Date.now() возвращает системное календарное время и может измениться из-за синхронизации часов. Для измерения длительности используй performance.now(), где доступно: это монотонная шкала. setTimeout задаёт минимальную задержку до постановки callback в очередь, а не гарантированное время запуска. Длинная синхронная задача блокирует event loop и задерживает таймеры. Для периодических задач учитывай дрейф, пропущенные интервалы, отмену и очистку ресурсов.','const start = performance.now(); await task(); const elapsed = performance.now() - start измеряет длительность независимо от коррекции системных часов.','Реализуй периодический scheduler с абсолютным следующим дедлайном, отменой через AbortSignal и политикой пропуска просроченных запусков. Смоделируй задержку callback и докажи тестами, что дрейф не накапливается.','Какой источник времени предпочтителен для измерения длительности?',['Date.now()','performance.now()','Строка new Date()'],1,refs.js,25),
lesson('JavaScript · Безопасная сериализация и восстановление состояния','Проектировать версионируемый формат хранения без потери данных.','JSON поддерживает ограниченный набор значений: undefined и функции не сериализуются как обычные свойства, циклические ссылки вызывают ошибку, Date превращается в строку. Надёжный формат хранения включает version, явную схему, проверку входа и миграции по цепочке. Миграция должна быть идемпотентной либо защищённой транзакцией; неизвестную более новую версию нельзя молча перезаписывать старой программой.','{version:2,data:{...}} позволяет сначала проверить версию, затем преобразовать v1 в v2 и валидировать результат до сохранения.','Спроектируй миграцию настроек v1→v2. Добавь тесты на повреждённый JSON, неизвестную версию, повторный запуск миграции и сохранение неизвестных пользовательских полей.','Что делать при обнаружении версии данных новее поддерживаемой приложением?',['Не перезаписывать её старой схемой; сохранить данные и сообщить о несовместимости','Сбросить хранилище к пустому объекту','Игнорировать version и записать текущую схему'],0,refs.js,30),
lesson('JavaScript · Конкурентные запросы и защита от гонок','Предотвращать применение устаревшего результата асинхронной операции.','При быстрых повторных действиях несколько запросов могут завершиться не в порядке запуска. Последний завершившийся ответ не обязательно относится к последнему пользовательскому намерению. Используй AbortController, монотонный requestId или проверку актуального ключа перед записью результата. Отмена экономит ресурсы, но проверка актуальности всё равно нужна: не каждый API гарантирует мгновенную отмену.','const id=++latest; const result=await load(); if(id!==latest)return; render(result) не позволяет старому ответу затереть новый.','Сделай поиск с debounce и отменой предыдущего запроса. Напиши управляемый тест, где первый запрос завершается позже второго, и проверь, что UI показывает только актуальные данные.','Какой механизм защищает UI от позднего устаревшего ответа?',['Проверка идентификатора актуального запроса перед применением результата','Увеличение timeout у каждого запроса','Сортировка ответов по размеру'],0,refs.js,25)
);
pyLessons.push(
lesson('Python · Контекстные менеджеры и собственные ресурсы','Создавать безопасные контекстные менеджеры для внешних ресурсов.','Контекстный менеджер задаёт протокол входа и выхода из блока with. Реализация через __enter__/__exit__ подходит для объектов с состоянием; contextlib.contextmanager позволяет выразить тот же жизненный цикл генератором с yield. Метод __exit__ получает сведения об исключении и может подавить его только осознанно. Освобождение ресурса должно происходить в finally-подобной части даже при ошибке внутри блока.','@contextmanager def managed(): acquire(); try: yield resource finally: release() гарантирует release при обычном выходе и исключении.','Реализуй контекстный менеджер временной блокировки ресурса. Проверь нормальный выход, исключение внутри блока, повторное использование и корректное поведение при ошибке acquire.','Когда __exit__ должен возвращать True?',['Когда исключение намеренно обработано и должно быть подавлено','Всегда для ускорения программы','Когда нужно повторить блок автоматически'],0,refs.py,25),
lesson('Python · Конкурентность: asyncio и отмена задач','Управлять конкурентными IO-операциями и корректно обрабатывать отмену.','asyncio предназначен прежде всего для конкурентного ожидания IO в одном event loop. await отдаёт управление циклу событий, позволяя другим задачам выполняться. CancelledError сигнализирует отмену; очистку ресурсов выполняй в try/finally и не подавляй отмену без веской причины. Для независимых задач используй TaskGroup в поддерживаемых версиях Python: структурированная конкурентность упрощает сбор результатов и распространение ошибок.','async with asyncio.TaskGroup() as group: group.create_task(fetch_a()); group.create_task(fetch_b()) связывает жизненный цикл дочерних задач с блоком.','Создай асинхронный сборщик трёх источников с общим deadline, отменой при критической ошибке и гарантированной очисткой. Проверь частичный отказ и отмену родительской задачи.','Для какого типа задач asyncio обычно наиболее полезен?',['Конкурентные операции ожидания IO','Тяжёлые CPU-вычисления без выноса в процессы','Любые задачи, которые должны исполняться параллельно на ядрах'],0,refs.py,30),
lesson('Python · Профилирование и измерение производительности','Находить узкие места измерениями, а не предположениями.','Оптимизация начинается с воспроизводимого workload и базовой метрики. timeit подходит для небольших фрагментов, cProfile — для анализа распределения времени по функциям, tracemalloc — для отслеживания выделений Python-памяти. Разделяй CPU time, wall time, latency и throughput. Сравнивай несколько прогонов, учитывай прогрев, шум окружения и репрезентативность данных; микрооптимизация без профиля часто ухудшает читаемость без заметной пользы.','Профиль может показать, что основное время уходит не в цикл обработки, а в повторный разбор JSON внутри каждой итерации.','Сними профиль учебного ETL-скрипта на фиксированном наборе данных. Найди три главных источника затрат, оптимизируй только один и сравни медиану нескольких прогонов.','Какой инструмент помогает увидеть распределение времени по функциям?',['cProfile','json','venv'],0,refs.py,25)
);
englishLessons.push(
lesson('A1 · Артикли a/an и базовая категория предмета','Выбирать a или an перед исчисляемым существительным в единственном числе.','A/an вводит один неопределённый предмет или представителя класса. Выбор зависит от первого звука следующего слова, а не от первой буквы: an apple, a university. Перед множественным числом и неисчисляемыми существительными в общем значении артикль обычно не ставится. На начальном уровне важно замечать существительное и проверять, исчисляемо ли оно в данном значении.','She has an umbrella. He is a teacher. We need water.','Составь 12 коротких предложений: 6 с a, 4 с an и 2 без артикля. Подчеркни существительное и объясни выбор.','Какой вариант верен?',['an university','a university','a umbrella'],1,refs.en,15),
lesson('A2 · Исчисляемые и неисчисляемые существительные','Использовать much, many, a few и a little с подходящими типами существительных.','Many и a few употребляются с исчисляемыми существительными во множественном числе; much и a little — с неисчисляемыми. A few означает небольшое, но достаточное количество; few подчёркивает нехватку. A little и little различаются похожим образом. В разговорной утвердительной речи вместо much часто естественнее использовать a lot of.','There are a few chairs, but there is little space. How much time do we have?','Опиши кухню или рабочее место в 100 словах, используя минимум по два примера many, much, a few и a little.','Что сочетается с неисчисляемым time?',['many time','much time','a few time'],1,refs.en,18),
lesson('B1 · Косвенная речь и согласование времён','Передавать чужие слова, сохраняя смысл и временную перспективу.','В косвенной речи после глагола сообщения в прошедшем времени часто происходит backshift: present simple переходит в past simple, will — в would, can — в could. Но с актуальными фактами и когда временная перспектива не изменилась, backshift необязателен. Вопросы становятся утвердительными по порядку слов; do/does/did обычно исчезают.','“I am busy,” she said. → She said that she was busy. “Where do you live?” → He asked where I lived.','Преобразуй 10 прямых высказываний и вопросов в косвенную речь. Для трёх примеров объясни, почему backshift обязателен или необязателен.','Как меняется порядок слов в косвенном вопросе?',['Используется обычный утвердительный порядок слов','Сохраняется инверсия вспомогательного глагола','Всегда добавляется do'],0,refs.en,20),
lesson('B2 · Инверсия для эмфазы и формального регистра','Использовать ограниченную инверсию для подчёркивания смысла в формальной речи.','После отрицательных или ограничительных наречий в начале предложения часто используется инверсия вспомогательного и подлежащего: Never have I seen..., Rarely does the team... . Инверсия также встречается с Not only..., но конструкция требует параллельной структуры. Это стилистический инструмент, а не универсальная замена обычному порядку слов; чрезмерное применение делает текст искусственным.','Not only did the proposal reduce costs, but it also improved reliability.','Перепиши шесть нейтральных предложений с Never, Rarely, Not until и Not only. Проверь вспомогательный глагол и параллелизм частей.','Как правильно построить инверсию после Rarely?',['Rarely the team has failed.','Rarely has the team failed.','Rarely did the team has failed.'],1,refs.en,22),
lesson('C1 · Прагматическое смягчение и дипломатическое несогласие','Выражать несогласие, степень уверенности и критику с точной прагматической силой.','В профессиональной коммуникации формулировка управляет не только буквальным содержанием, но и отношениями. I see your point, however... признаёт позицию собеседника; I would question whether... смягчает прямое оспаривание; The evidence appears insufficient точнее, чем This is wrong, если вывод предварительный. Смягчение не должно скрывать существенный риск или превращать ясную рекомендацию в двусмысленность.','I agree with the objective; I am less convinced that the proposed timeline accounts for the integration risk.','Подготовь ответ на спорное предложение коллеги: признай сильную сторону, сформулируй конкретное возражение, приведи основание и предложи альтернативу.','Какая формулировка выражает осторожное сомнение?',['I would question whether the sample is representative.','You are obviously wrong.','There is no possible discussion.'],0,refs.en,25),
lesson('C2 · Риторическая композиция и управление вниманием читателя','Создавать сложный текст, в котором риторическая структура поддерживает доказательство.','На уровне C2 управление дискурсом включает тематическое развитие, контраст, уступку, фокусирование и контролируемое повторное введение терминов. Параллельные конструкции усиливают сопоставление; cleft sentences выделяют фокус; концовка абзаца может подготавливать следующий шаг аргумента. Риторическая сложность оправдана только тогда, когда повышает точность и убедительность, а не маскирует слабые доказательства.','What matters is not the volume of evidence, but its relevance, independence and quality.','Отредактируй аналитический текст на 500 слов: обозначь фокус каждого абзаца, усили контрасты, убери повторения без потери терминологической точности и обоснуй три композиционных решения.','Что должно оправдывать сложный риторический приём?',['Его вклад в ясность, фокус и доказательность','Сам факт высокого уровня владения грамматикой','Увеличение длины текста'],0,refs.en,30)
);

